@@ -2,6 +2,7 @@

 const validator = require('validator');

+const db = require('../../database');
 const api = require('../../api');
 const topics = require('../../topics');
 const privileges = require('../../privileges');
@@ -12,22 +13,38 @@ const uploadsController = require('../uploads');

 const Topics = module.exports;

+// Safety-net TTL (ms) for the posting lock. The lock is released as soon as
+// the request completes, so this only matters if a request is interrupted
+// without releasing it (eg. process crash), keeping a user from being
+// blocked from posting indefinitely.
+const postingLockTTL = 30000;
+
 Topics.get = async (req, res) => {
 	helpers.formatApiResponse(200, res, await api.topics.get(req, req.params));
 };

 Topics.create = async (req, res) => {
-	const payload = await api.topics.create(req, req.body);
-	if (payload.queued) {
-		helpers.formatApiResponse(202, res, payload);
-	} else {
-		helpers.formatApiResponse(200, res, payload);
+	const lockKey = await Topics.lockPosting(req, '[[error:api.400]]');
+	try {
+		const payload = await api.topics.create(req, req.body);
+		if (payload.queued) {
+			helpers.formatApiResponse(202, res, payload);
+		} else {
+			helpers.formatApiResponse(200, res, payload);
+		}
+	} finally {
+		await Topics.unlockPosting(lockKey);
 	}
 };

 Topics.reply = async (req, res) => {
-	const payload = await api.topics.reply(req, { ...req.body, tid: req.params.tid });
-	helpers.formatApiResponse(200, res, payload);
+	const lockKey = await Topics.lockPosting(req, '[[error:api.400]]');
+	try {
+		const payload = await api.topics.reply(req, { ...req.body, tid: req.params.tid });
+		helpers.formatApiResponse(200, res, payload);
+	} finally {
+		await Topics.unlockPosting(lockKey);
+	}
 };

 Topics.delete = async (req, res) => {
@@ -219,3 +236,54 @@ Topics.deleteEvent = async (req, res) => {
 	await topics.events.purge(req.params.tid, [req.params.eventId]);
 	helpers.formatApiResponse(200, res);
 };
+
+// Lightweight per-actor lock to prevent concurrent posting actions (create
+// topic / reply) from the same authenticated user or guest session.
+// Acquires a lock keyed on the actor's uid (or sessionID for guests) so that
+// only one create/reply request is processed at a time per actor.
+//
+// Inputs:
+// - req: Request object containing either `uid` for authenticated users or
+//        `sessionID` for guests.
+// - error: String used to raise an error if a concurrent posting attempt is
+//          detected.
+//
+// Outputs:
+// - Returns the string key (`posting<id>`) that uniquely identifies the lock
+//   for the user/session.
+// - Throws an error with the provided `error` message if another posting
+//   action is already in progress for the same user/session.
+Topics.lockPosting = async function (req, error) {
+	const id = req.uid || req.sessionID;
+	const key = `posting${id}`;
+
+	if (db.client && typeof db.client.set === 'function') {
+		// SET ... NX is atomic, exactly one of the concurrent requests wins
+		const result = await db.client.set(key, String(Date.now()), 'NX', 'PX', postingLockTTL);
+		if (result !== 'OK') {
+			throw new Error(error);
+		}
+	} else {
+		// Fallback for database backends without atomic set-if-absent
+		if (await db.exists(key)) {
+			throw new Error(error);
+		}
+		await db.set(key, String(Date.now()));
+		await db.pexpire(key, postingLockTTL);
+	}
+
+	return key;
+};
+
+// Releases a lock previously acquired with `lockPosting`. Best effort: the
+// lock is guaranteed to expire via its TTL even if this fails.
+Topics.unlockPosting = async function (key) {
+	if (!key) {
+		return;
+	}
+	try {
+		await db.delete(key);
+	} catch (e) {
+		// swallow, lock will expire via TTL
+	}
+};
diff --git a/test/concurrent-topics.js b/test/concurrent-topics.js
new file mode 100644
index 000000000..de69e1c0c
--- /dev/null
+++ b/test/concurrent-topics.js
@@ -0,0 +1,148 @@
+'use strict';
+
+const assert = require('assert');
+
+const db = require('./mocks/databasemock');
+const categories = require('../src/categories');
+const privileges = require('../src/privileges');
+const user = require('../src/user');
+const helpers = require('./helpers');
+
+describe('Concurrent topic creation', () => {
+	let categoryObj;
+	let uid;
+	let jar;
+
+	before(async () => {
+		uid = await user.create({ username: 'concurrentuser', password: '123456' });
+		categoryObj = await categories.create({ name: 'Concurrent Test Category' });
+		({ jar } = await helpers.loginUser('concurrentuser', '123456'));
+	});
+
+	it('should only create one topic when multiple concurrent create requests are issued by the same user', async function () {
+		this.timeout(60000);
+
+		const topicCountBefore = parseInt(await db.getObjectField('global', 'topicCount'), 10) || 0;
+		const categoryCountBefore = parseInt(await db.getObjectField(`category:${categoryObj.cid}`, 'topic_count'), 10) || 0;
+
+		const N = 5;
+		const payload = {
+			cid: categoryObj.cid,
+			title: 'Concurrent Topic',
+			content: 'Concurrent topic content',
+		};
+
+		const results = await Promise.all(Array.from({ length: N }, () => helpers.request('post', `/api/v3/topics`, {
+			form: payload,
+			jar,
+			json: true,
+		})));
+
+		const successes = results.filter(({ res, body }) => res.statusCode === 200 && body.status && body.status.code === 'ok');
+		const rejections = results.filter(({ res, body }) => res.statusCode === 400 && body.status && body.status.code === 'bad-request');
+
+		assert.strictEqual(successes.length, 1, `expected exactly 1 successful request, got ${successes.length}`);
+		assert.strictEqual(rejections.length, N - 1, `expected ${N - 1} rejected requests, got ${rejections.length}`);
+
+		const topicCountAfter = parseInt(await db.getObjectField('global', 'topicCount'), 10) || 0;
+		const categoryCountAfter = parseInt(await db.getObjectField(`category:${categoryObj.cid}`, 'topic_count'), 10) || 0;
+		assert.strictEqual(topicCountAfter, topicCountBefore + 1, 'global topicCount should reflect exactly one new topic');
+		assert.strictEqual(categoryCountAfter, categoryCountBefore + 1, 'category topic_count should reflect exactly one new topic');
+
+		const userTopicCount = await db.sortedSetCard(`uid:${uid}:topics`);
+		assert.strictEqual(userTopicCount, 1, 'user should have exactly one topic');
+	});
+
+	it('should allow a subsequent create request once the overlapping ones have completed', async function () {
+		this.timeout(60000);
+
+		const result = await helpers.request('post', `/api/v3/topics`, {
+			form: {
+				cid: categoryObj.cid,
+				title: 'Sequential Topic',
+				content: 'Sequential topic content',
+			},
+			jar,
+			json: true,
+		});
+		assert.strictEqual(result.res.statusCode, 200);
+		assert.strictEqual(result.body.status.code, 'ok');
+	});
+
+	describe('guests', () => {
+		before(async () => {
+			await privileges.categories.give(['groups:topics:create'], categoryObj.cid, 'guests');
+		});
+
+		it('should only accept one of multiple concurrent create requests from the same guest session', async function () {
+			this.timeout(60000);
+
+			const topicCountBefore = parseInt(await db.getObjectField('global', 'topicCount'), 10) || 0;
+
+			const guestJar = require('request').jar();
+			// Establish the guest session (as a browser would on first page load)
+			await helpers.request('get', `/api/config`, {
+				jar: guestJar,
+				json: true,
+			});
+
+			const N = 3;
+			const results = await Promise.all(Array.from({ length: N }, () => helpers.request('post', `/api/v3/topics`, {
+				form: {
+					cid: categoryObj.cid,
+					title: 'Concurrent Guest Topic',
+					content: 'Concurrent guest topic content',
+				},
+				jar: guestJar,
+				json: true,
+			})));
+
+			const successes = results.filter(({ res, body }) => res.statusCode === 200 && body.status && body.status.code === 'ok');
+			const rejections = results.filter(({ res, body }) => res.statusCode === 400 && body.status && body.status.code === 'bad-request');
+
+			assert.strictEqual(successes.length, 1, `expected exactly 1 successful guest request, got ${successes.length}`);
+			assert.strictEqual(rejections.length, N - 1, `expected ${N - 1} rejected guest requests, got ${rejections.length}`);
+
+			const topicCountAfter = parseInt(await db.getObjectField('global', 'topicCount'), 10) || 0;
+			assert.strictEqual(topicCountAfter, topicCountBefore + 1, 'global topicCount should reflect exactly one new guest topic');
+		});
+
+		it('should not block a different guest session while one is in-flight', async function () {
+			this.timeout(60000);
+
+			const topicCountBefore = parseInt(await db.getObjectField('global', 'topicCount'), 10) || 0;
+
+			const guestJarA = require('request').jar();
+			const guestJarB = require('request').jar();
+			await helpers.request('get', `/api/config`, { jar: guestJarA, json: true });
+			await helpers.request('get', `/api/config`, { jar: guestJarB, json: true });
+
+			const results = await Promise.all([
+				helpers.request('post', `/api/v3/topics`, {
+					form: {
+						cid: categoryObj.cid,
+						title: 'Guest A Topic',
+						content: 'Guest A topic content',
+					},
+					jar: guestJarA,
+					json: true,
+				}),
+				helpers.request('post', `/api/v3/topics`, {
+					form: {
+						cid: categoryObj.cid,
+						title: 'Guest B Topic',
+						content: 'Guest B topic content',
+					},
+					jar: guestJarB,
+					json: true,
+				}),
+			]);
+
+			const successes = results.filter(({ res, body }) => res.statusCode === 200 && body.status && body.status.code === 'ok');
+			assert.strictEqual(successes.length, 2, `expected both guest requests (different sessions) to succeed, got ${successes.length}`);
+
+			const topicCountAfter = parseInt(await db.getObjectField('global', 'topicCount'), 10) || 0;
+			assert.strictEqual(topicCountAfter, topicCountBefore + 2, 'global topicCount should reflect two new guest topics');
+		});
+	});
+});

