diff --git a/src/controllers/well-known.js b/src/controllers/well-known.js
new file mode 100644
index 0000000000..8d2d1d2d1d
--- /dev/null
+++ b/src/controllers/well-known.js
@@ -0,0 +1,72 @@
+'use strict';
+
+const nconf = require('nconf');
+
+const user = require('../user');
+const privileges = require('../privileges');
+const helpers = require('../middleware/helpers');
+
+const wellKnown = module.exports;
+
+/**
+ * GET /.well-known/webfinger?resource=acct:<userslug>@<hostname>
+ *
+ * Serves WebFinger (RFC 7033) discovery documents for federated identity.
+ * Access is gated on the `groups:view:users` global privilege; anonymous
+ * requests are evaluated as the Guest role (uid 0).
+ */
+wellKnown.webfinger = helpers.try(async (req, res) => {
+	const resource = req.query.resource;
+	const hostname = nconf.get('url_parsed').hostname;
+
+	// Resource must be an acct: URI targeting this site, e.g. `acct:pia@localhost`
+	if (
+		typeof resource !== 'string' ||
+		!resource.startsWith('acct:') ||
+		!resource.endsWith(`@${hostname}`)
+	) {
+		return res.status(400).json({ error: '[[error:invalid-argument]]' });
+	}
+
+	const username = resource.slice('acct:'.length, -(hostname.length + 1));
+	if (!username) {
+		return res.status(400).json({ error: '[[error:invalid-argument]]' });
+	}
+
+	// Gate discovery on the groups:view:users global privilege.
+	// req.uid is absent for anonymous requests, so evaluate as Guest (uid 0).
+	const uid = req.uid || 0;
+	const allowed = await privileges.global.can('view:users', uid);
+	if (!allowed) {
+		return res.status(403).json({ error: '[[error:not-allowed]]' });
+	}
+
+	// Resolve the username (slug) portion of the resource to a uid
+	const targetUid = (await user.getUidByUserslug(username)) || await user.getUidByUsername(username);
+	if (!targetUid) {
+		return res.status(404).json({ error: '[[error:user-not-found]]' });
+	}
+
+	const base = nconf.get('url');
+	const profileUrl = `${base}/user/${username}`;
+	const uidUrl = `${base}/uid/${targetUid}`;
+
+	const webfinger = {
+		subject: resource,
+		aliases: [uidUrl, profileUrl],
+		links: [
+			{
+				rel: 'http://webfinger.net/rel/profile-page',
+				type: 'text/html',
+				href: profileUrl,
+			},
+			{
+				rel: 'lrdd',
+				type: 'application/json',
+				href: `${base}/.well-known/webfinger?resource=`,
+			},
+		],
+	};
+
+	res.status(200).json(webfinger);
+});
