+
+import * as React from "react";
+
+// A keyboard shortcut, as a combination of a key and optional modifiers.
+export interface KeyCombo {
+    // The key which must be pressed, e.g. Key.B or "f".
+    // Compared case-insensitively.
+    key: string;
+
+    // The Control key must be held.
+    ctrlKey?: boolean;
+    // The Alt key must be held.
+    altKey?: boolean;
+    // The Shift key must be held. Ignored when matching letter keys, as Shift
+    // is what determines the case of the reported key.
+    shiftKey?: boolean;
+    // The Meta key (Windows/Cmd key) must be held.
+    metaKey?: boolean;
+    // The "primary" modifier must be held: Command on macOS, Control on
+    // Windows and Linux.
+    ctrlOrCmd?: boolean;
+}
+
+// True if the key is a single letter (a-z or A-Z).
+function isLetterKey(key: string): boolean {
+    const lower = key.toLowerCase();
+    return key.length === 1 && lower >= "a" && lower <= "z";
+}
+
+/**
+ * Checks whether a keyboard event exactly matches a key combination.
+ *
+ * A match requires:
+ *  - the pressed key to equal `combo.key` (case-insensitively);
+ *  - every modifier required by the combo to be held;
+ *  - no unrelated modifiers to be held, so that e.g. Ctrl+Alt+A does not
+ *    trigger a binding for Ctrl+A. (The only exception is Shift for letter
+ *    keys, see below.)
+ *
+ * `ctrlOrCmd` is interpreted as the Meta (Command) key when `onMac` is true,
+ * and as the Control key otherwise.
+ *
+ * For letter keys, the Shift modifier does not break the match: pressing
+ * Shift+A reports the key as "A" with shiftKey set, which must still match
+ * a binding for "a" (and vice versa). If the combo explicitly requires
+ * Shift, it must still be held.
+ *
+ * @param ev The keyboard event to check.
+ * @param combo The key combination to check against.
+ * @param onMac Whether the current platform is macOS (Command vs Control).
+ * @returns True if the event matches the combination exactly, false otherwise.
+ */
+export function isKeyComboMatch(
+    ev: KeyboardEvent | React.KeyboardEvent,
+    combo: KeyCombo,
+    onMac: boolean,
+): boolean {
+    // The key must match, case-insensitively, so that "A" and "a" are
+    // interchangeable regardless of capitalization.
+    const evKey = (ev.key || "").toLowerCase();
+    const comboKey = combo.key.toLowerCase();
+    if (evKey !== comboKey) {
+        return false;
+    }
+
+    // Work out which physical modifiers the combination requires.
+    // `ctrlOrCmd` maps to the Command key on macOS and Control elsewhere.
+    const requiresCtrl = !!combo.ctrlKey || (!!combo.ctrlOrCmd && !onMac);
+    const requiresMeta = !!combo.metaKey || (!!combo.ctrlOrCmd && onMac);
+    const requiresAlt = !!combo.altKey;
+    const requiresShift = !!combo.shiftKey;
+
+    // Coerce so that events which omit a modifier property (e.g. plain
+    // objects simulating key events) are treated as "not held".
+    const hasCtrl = !!ev.ctrlKey;
+    const hasMeta = !!ev.metaKey;
+    const hasAlt = !!ev.altKey;
+    const hasShift = !!ev.shiftKey;
+
+    // Every required modifier must be held, and no unrequired modifier may be.
+    if (hasCtrl !== requiresCtrl) {
+        return false;
+    }
+    if (hasMeta !== requiresMeta) {
+        return false;
+    }
+    if (hasAlt !== requiresAlt) {
+        return false;
+    }
+
+    // If the combo requires Shift, it must be held.
+    if (requiresShift && !hasShift) {
+        return false;
+    }
+
+    // For letter keys, an unexpected Shift only affects the case of the
+    // reported key, which we already compared case-insensitively, so it must
+    // not break the match. For other keys, an unexpected Shift is an extra,
+    // unrelated modifier and must not trigger the binding.
+    if (!requiresShift && hasShift && !isLetterKey(comboKey)) {
+        return false;
+    }
+
+    return true;
+}
