+const {isKeyComboMatch} = require("../src/KeyBindingsManager");
+
+// Simulates a keyboard event as a plain object (some properties omitted,
+// as synthetic/plain-object events often are).
+function keyEvent(key, mods = {}) {
+    return Object.assign({key}, mods);
+}
+
+describe("isKeyComboMatch", () => {
+    describe("basic key matching", () => {
+        it("matches when key is equal", () => {
+            expect(isKeyComboMatch(keyEvent("a"), {key: "a"}, false)).toBe(true);
+            expect(isKeyComboMatch(keyEvent("Enter"), {key: "Enter"}, false)).toBe(true);
+            expect(isKeyComboMatch(keyEvent("F1"), {key: "F1"}, true)).toBe(true);
+        });
+
+        it("does not match when the key differs", () => {
+            expect(isKeyComboMatch(keyEvent("a"), {key: "b"}, false)).toBe(false);
+            expect(isKeyComboMatch(keyEvent("Enter"), {key: "Escape"}, false)).toBe(false);
+        });
+    });
+
+    describe("capitalization of letter keys", () => {
+        it("matches letters regardless of the case of the combo", () => {
+            const combo = {key: "a"};
+            expect(isKeyComboMatch(keyEvent("a"), combo, false)).toBe(true);
+            expect(isKeyComboMatch(keyEvent("A"), combo, false)).toBe(true);
+
+            const comboUpper = {key: "A"};
+            expect(isKeyComboMatch(keyEvent("a"), comboUpper, true)).toBe(true);
+            expect(isKeyComboMatch(keyEvent("A"), comboUpper, true)).toBe(true);
+        });
+
+        it("does not let Shift break a match for letter keys", () => {
+            const combo = {key: "a"};
+            expect(isKeyComboMatch(keyEvent("A", {shiftKey: true}), combo, false)).toBe(true);
+            expect(isKeyComboMatch(keyEvent("A", {shiftKey: true}), combo, true)).toBe(true);
+        });
+
+        it("treats unexpected Shift as an extra modifier for non-letter keys", () => {
+            const combo = {key: "F1"};
+            expect(isKeyComboMatch(keyEvent("F1", {shiftKey: true}), combo, false)).toBe(false);
+            expect(isKeyComboMatch(keyEvent("F1"), combo, false)).toBe(true);
+        });
+    });
+
+    describe("ctrlOrCmd", () => {
+        const combo = {key: "a", ctrlOrCmd: true};
+
+        it("uses Control on Windows/Linux", () => {
+            expect(isKeyComboMatch(keyEvent("a", {ctrlKey: true}), combo, false)).toBe(true);
+            // meta alone is not ctrl
+            expect(isKeyComboMatch(keyEvent("a", {metaKey: true}), combo, false)).toBe(false);
+            // extra modifier
+            expect(isKeyComboMatch(keyEvent("a", {ctrlKey: true, metaKey: true}), combo, false)).toBe(false);
+            // missing modifier
+            expect(isKeyComboMatch(keyEvent("a"), combo, false)).toBe(false);
+        });
