+            // ctrl alone is not cmd
+            expect(isKeyComboMatch(keyEvent("a", {ctrlKey: true}), combo, true)).toBe(false);
+            // extra modifier
+            expect(isKeyComboMatch(keyEvent("a", {ctrlKey: true, metaKey: true}), combo, true)).toBe(false);
+            // missing modifier
+            expect(isKeyComboMatch(keyEvent("a"), combo, true)).toBe(false);
+        });
+
+        it("still works with Shift for letter keys", () => {
+            expect(isKeyComboMatch(keyEvent("A", {ctrlKey: true, shiftKey: true}), combo, false)).toBe(true);
+            expect(isKeyComboMatch(keyEvent("A", {metaKey: true, shiftKey: true}), combo, true)).toBe(true);
+        });
+    });
+
+    describe("explicit ctrlKey / metaKey", () => {
+        it("matches explicit ctrlKey on any platform", () => {
+            const combo = {key: "a", ctrlKey: true};
+            expect(isKeyComboMatch(keyEvent("a", {ctrlKey: true}), combo, true)).toBe(true);
+            expect(isKeyComboMatch(keyEvent("a", {metaKey: true}), combo, true)).toBe(false);
+        });
+
+        it("matches explicit metaKey on any platform", () => {
+            const combo = {key: "a", metaKey: true};
+            expect(isKeyComboMatch(keyEvent("a", {metaKey: true}), combo, false)).toBe(true);
+            expect(isKeyComboMatch(keyEvent("a", {ctrlKey: true}), combo, false)).toBe(false);
+        });
+    });
+
+    describe("exact modifier matching", () => {
+        it("fails when extra modifiers are held", () => {
+            const combo = {key: "a", ctrlOrCmd: true};
+            const f1Combo = {key: "F1", ctrlOrCmd: true};
+            const evCtrlAlt = keyEvent("a", {ctrlKey: true, altKey: true});
+            const evCtrlShift = keyEvent("a", {ctrlKey: true, shiftKey: true});
+            const evF1CtrlAlt = keyEvent("F1", {ctrlKey: true, altKey: true});
+            expect(isKeyComboMatch(evCtrlAlt, combo, false)).toBe(false);
+            expect(isKeyComboMatch(evCtrlShift, f1Combo, false)).toBe(false);
+            expect(isKeyComboMatch(evF1CtrlAlt, f1Combo, false)).toBe(false);
+        });
+
+        it("fails when required modifiers are missing", () => {
+            const combo = {key: "a", ctrlOrCmd: true, altKey: true};
+            expect(isKeyComboMatch(keyEvent("a", {ctrlKey: true}), combo, false)).toBe(false);
+            expect(isKeyComboMatch(keyEvent("a", {ctrlKey: true, metaKey: true}), combo, true)).toBe(false);
+
+            // explicitly required Shift must still be held
+            expect(isKeyComboMatch(keyEvent("a"), {key: "a", shiftKey: true}, false)).toBe(false);
+            expect(isKeyComboMatch(keyEvent("a", {shiftKey: true}), {key: "a", shiftKey: true}, false)).toBe(true);
+        });
+    });
+
+    describe("multiple modifiers (Ctrl+Alt+Shift)", () => {
+        const combo = {key: "u", ctrlOrCmd: true, altKey: true, shiftKey: true};
+
+        it("matches when all modifiers are held", () => {
+            const evWin = keyEvent("U", {ctrlKey: true, altKey: true, shiftKey: true});
+            const evMac = keyEvent("U", {metaKey: true, altKey: true, shiftKey: true});
+            expect(isKeyComboMatch(evWin, combo, false)).toBe(true);
+            expect(isKeyComboMatch(evMac, combo, true)).toBe(true);
+        });
+
+        it("fails when any modifier is missing or extra", () => {
+            const evNoShift = keyEvent("U", {ctrlKey: true, altKey: true});
+            const evNoAlt = keyEvent("U", {ctrlKey: true, shiftKey: true});
+            const evNoCtrl = keyEvent("U", {altKey: true, shiftKey: true});
+            const evExtraMeta = keyEvent("U", {ctrlKey: true, altKey: true, shiftKey: true, metaKey: true});
+            expect(isKeyComboMatch(evNoShift, combo, false)).toBe(false);
+            expect(isKeyComboMatch(evNoAlt, combo, false)).toBe(false);
+            expect(isKeyComboMatch(evNoCtrl, combo, false)).toBe(false);
+            expect(isKeyComboMatch(evExtraMeta, combo, false)).toBe(false);
+        });
+
+        it("supports explicit ctrlKey with altKey and shiftKey", () => {
+            const combo2 = {key: "u", ctrlKey: true, altKey: true, shiftKey: true};
+            const ev = keyEvent("U", {ctrlKey: true, altKey: true, shiftKey: true});
+            expect(isKeyComboMatch(ev, combo2, true)).toBe(true);
+            expect(isKeyComboMatch(ev, combo2, false)).toBe(true);
+        });
+    });
+
+    describe("events with omitted modifier properties", () => {
+        it("treats missing modifier properties as not held", () => {
+            // plain object event with no metaKey/altKey/shiftKey properties at all
+            expect(isKeyComboMatch(keyEvent("a", {ctrlKey: true}), {key: "a", ctrlOrCmd: true}, false)).toBe(true);
+            expect(isKeyComboMatch(keyEvent("a", {metaKey: true}), {key: "a", ctrlOrCmd: true}, true)).toBe(true);
+            expect(isKeyComboMatch(keyEvent("a"), {key: "a"}, false)).toBe(true);
+        });
+    });
+
+    describe("native KeyboardEvent objects", () => {
+        it("matches real KeyboardEvent instances", () => {
+            const combo = {key: "a", ctrlOrCmd: true};
+            const ev = new KeyboardEvent("keydown", {key: "A", ctrlKey: true, shiftKey: true});
+            expect(isKeyComboMatch(ev, combo, false)).toBe(true);
+
+            const ev2 = new KeyboardEvent("keydown", {key: "a", metaKey: true});
+            expect(isKeyComboMatch(ev2, combo, true)).toBe(true);
+
+            const ev3 = new KeyboardEvent("keydown", {key: "F1", shiftKey: true});
+            expect(isKeyComboMatch(ev3, {key: "F1"}, false)).toBe(false);
+        });
+    });
+});

