new file mode 100644
index 0000000000..bfe1a2de52
--- /dev/null
+++ b/src/components/views/rooms/EventPreview.tsx
@@ -0,0 +1,136 @@
+/*
+ * Copyright 2025 New Vector Ltd.
+ * Copyright 2025 The Matrix.org Foundation C.I.C.
+ *
+ * SPDX-License-Identifier: AGPL-3.0-only OR GPL-3.0-only
+ * Please see LICENSE files in the repository root for full details.
+ */
+
+import React, { JSX, useState } from "react";
+import { IContent, M_POLL_START, MatrixEvent, MatrixEventEvent, MsgType } from "matrix-js-sdk/src/matrix";
+import classNames from "classnames";
+
+import { useAsyncMemo } from "../../../hooks/useAsyncMemo";
+import { useTypedEventEmitter } from "../../../hooks/useEventEmitter";
+import { _t } from "../../../languageHandler";
+import { MatrixClientPeg } from "../../../MatrixClientPeg";
+import { MessagePreviewStore } from "../../../stores/room-list/MessagePreviewStore";
+
+/**
+ * A tuple representing the preview text of an event and an optional, localized prefix
+ * describing the type of the message (e.g. "Image", "Audio", "Poll").
+ */
+export type Preview = [preview: string, prefix: string | null];
+
+/**
+ * The props for the {@link EventPreviewTile} component.
+ */
+interface EventPreviewTileProps extends React.HTMLAttributes<HTMLSpanElement> {
+    /**
+     * The preview text and the optional prefix to render
+     */
+    preview: Preview;
+    /**
+     * Additional CSS class names to apply to the preview
+     */
+    className?: string;
+}
+
+/**
+ * A component that renders a message preview along with an optional type prefix in a styled span.
+ */
+export function EventPreviewTile({ preview, className, ...props }: EventPreviewTileProps): JSX.Element | null {
+    const [messagePreview, prefix] = preview;
+    if (!messagePreview) return null;
+
+    return (
+        <span className={classNames("mx_EventPreview", className)} {...props}>
+            {prefix && <span className="mx_EventPreview_prefix">{prefix}: </span>}
+            {messagePreview}
+        </span>
+    );
+}
+
+/**
+ * The props for the {@link EventPreview} component.
+ */
+interface EventPreviewProps extends React.HTMLAttributes<HTMLSpanElement> {
+    /**
+     * The event to generate a preview for
+     */
+    mxEvent: MatrixEvent;
+    /**
+     * Additional CSS class names to apply to the preview
+     */
+    className?: string;
+}
+
+/**
+ * A component that renders a preview (with an optional type prefix) for a given event.
+ */
+export function EventPreview({ mxEvent, className, ...props }: EventPreviewProps): JSX.Element | null {
+    const preview = useEventPreview(mxEvent);
+    if (!preview) return null;
+
+    return <EventPreviewTile preview={preview} className={className} {...props} />;
+}
+
+/**
+ * A hook that generates a preview, along with an optional type prefix, for a given event.
+ *
+ * The preview is regenerated when the event is replaced (edited), decrypted, or when a new
+ * event is passed in.
+ *
+ * @param mxEvent The event to generate a preview for.
+ * @returns The preview and prefix for the event, or null if no preview can be generated.
+ */
+export function useEventPreview(mxEvent: MatrixEvent | undefined): Preview | null {
+    // track the content as a means to regenerate the preview upon edits & decryption
+    const [content, setContent] = useState<IContent | undefined>(mxEvent?.getContent());
+    useTypedEventEmitter(mxEvent, MatrixEventEvent.Replaced, () => {
+        setContent(mxEvent?.getContent());
+    });
+    const awaitDecryption = mxEvent?.shouldAttemptDecryption() || mxEvent?.isBeingDecrypted();
+    useTypedEventEmitter(awaitDecryption ? mxEvent : undefined, MatrixEventEvent.Decrypted, () => {
+        setContent(mxEvent?.getContent());
+    });
+
+    return useAsyncMemo<Preview | null>(
+        async (): Promise<Preview | null> => {
+            if (!mxEvent || mxEvent.isRedacted() || mxEvent.isDecryptionFailure()) return null;
+            await MatrixClientPeg.safeGet().decryptEventIfNeeded(mxEvent);
+
+            const preview = MessagePreviewStore.instance.generatePreviewForEvent(mxEvent);
+            if (!preview) return null;
+
+            return [preview, getPreviewPrefix(mxEvent)];
+        },
+        [mxEvent, content],
+        null,
+    );
+}
+
+/**
+ * Get the localized prefix for the preview based on the type and message type of the event.
+ * @param mxEvent The event to get the prefix for.
+ * @returns The prefix to display before the preview, or null if the event has no prefix.
+ */
+function getPreviewPrefix(mxEvent: MatrixEvent): string | null {
+    const type = mxEvent.getType();
+    if (type === M_POLL_START.name || type === M_POLL_START.altName) {
+        return _t("event_preview|prefix|poll");
+    }
+
+    switch (mxEvent.getContent()["msgtype"] as MsgType) {
+        case MsgType.Image:
+            return _t("event_preview|prefix|image");
+        case MsgType.Audio:
+            return _t("event_preview|prefix|audio");
+        case MsgType.Video:
+            return _t("event_preview|prefix|video");
+        case MsgType.File:
+            return _t("event_preview|prefix|file");
+        default:
+            return null;
+    }
+}
