+import { logger } from 'matrix-js-sdk/src/logger';
+
+import LegacyCallHandler, { AudioID } from '../src/LegacyCallHandler';
+import { AudioID as LegacyIndexAudioID, handleEvent } from '../src/legacy/LegacyCallHandler';
