+import SettingsStore from '../src/settings/SettingsStore';
+
+describe('call sound identifiers are public and stable', () => {
+    it('exposes AudioID from src/LegacyCallHandler', () => {
+        expect(AudioID.Ring).toEqual('ringAudio');
+        expect(AudioID.Ringback).toEqual('ringbackAudio');
+        expect(AudioID.CallEnd).toEqual('callendAudio');
+        expect(AudioID.Busy).toEqual('busyAudio');
+    });
+
+    it('re-exports the same identifiers from src/legacy/LegacyCallHandler', () => {
+        expect(LegacyIndexAudioID).toBe(AudioID);
+    });
+});
+
+describe('LegacyCallHandler.play recovers muted audio elements', () => {
+    let callHandler: LegacyCallHandler;
+    let audio: {
+        muted: boolean;
+        play: jest.Mock;
+    };
+
+    beforeEach(() => {
+        callHandler = new LegacyCallHandler();
+        audio = {
+            muted: true,
+            play: jest.fn().mockResolvedValue(undefined),
+        };
+        jest.spyOn(document, 'getElementById').mockReturnValue(audio as unknown as HTMLMediaElement);
+    });
+
+    afterEach(() => {
+        jest.restoreAllMocks();
+    });
+
+    it('unmutes a muted element and then plays', () => {
+        const order: Array<string | boolean> = [];
+        audio.play = jest.fn(() => {
+            order.push('play', audio.muted);
+            return Promise.resolve();
+        }) as jest.Mock;
+
+        callHandler.play(AudioID.Ring);
+
+        expect(audio.muted).toBe(false);
+        expect(audio.play).toHaveBeenCalledTimes(1);
+        // playback must be initiated after the mute state was corrected
+        expect(order[0]).toEqual('play');
+        expect(order[1]).toBe(false);
+    });
+
+    it('is idempotent for an already-unmuted element', () => {
+        let mutedValue = false;
+        let setterCalls = 0;
+        const freshAudio = {
+            play: jest.fn().mockResolvedValue(undefined),
+        };
+        Object.defineProperty(freshAudio, 'muted', {
+            get: () => mutedValue,
+            set: (v) => {
+                setterCalls += 1;
+                mutedValue = v;
+            },
+            configurable: true,
+        });
+        jest.spyOn(document, 'getElementById')
+            .mockReturnValue(freshAudio as unknown as HTMLMediaElement);
+
+        callHandler.play(AudioID.Ringback);
+
+        expect(freshAudio.play).toHaveBeenCalledTimes(1);
+        expect(mutedValue).toBe(false);
+        expect(setterCalls).toBe(0); // no unintended side effects
+    });
+
+    it('unmutes a real DOM element before playing', async () => {
+        const el = document.createElement('audio');
+        el.id = 'ringAudio';
+        el.muted = true;
+        document.body.appendChild(el);
+        jest.spyOn(document, 'getElementById').mockReturnValue(el);
+        jest.spyOn(HTMLMediaElement.prototype, 'play').mockResolvedValue(undefined);
+
+        callHandler.play(AudioID.Ring);
+        await new Promise(process.nextTick);
+
+        expect(el.muted).toBe(false);
+        expect(HTMLMediaElement.prototype.play).toHaveBeenCalled();
+
+        document.body.removeChild(el);
+    });
+
+    it('wires the media event handler onto real elements (error events are logged)', async () => {
+        const el = document.createElement('audio');
+        el.id = 'busyAudio';
+        document.body.appendChild(el);
+        jest.spyOn(document, 'getElementById').mockReturnValue(el);
+        jest.spyOn(HTMLMediaElement.prototype, 'play').mockResolvedValue(undefined);
+        const errorSpy = jest.spyOn(logger, 'error').mockImplementation(() => undefined);
+
+        callHandler.play(AudioID.Busy);
+        await new Promise(process.nextTick);
+
+        el.dispatchEvent(new Event('error'));
+        expect(errorSpy).toHaveBeenCalledTimes(1);
+        expect(String(errorSpy.mock.calls[0][0])).toContain('busyAudio');
+
+        document.body.removeChild(el);
+    });
+});
+
+describe('handleEvent', () => {
+    let errorSpy: jest.SpyInstance;
+    let debugSpy: jest.SpyInstance;
+
+    beforeEach(() => {
+        jest.restoreAllMocks();
+        errorSpy = jest.spyOn(logger, 'error').mockImplementation(() => undefined);
+        debugSpy = jest.spyOn(logger, 'debug').mockImplementation(() => undefined);
+        jest.spyOn(SettingsStore, 'getValue')
+            .mockImplementation(name => name === DEBUG_LEGACY_CALL_HANDLER_SETTING ? true : undefined);
+    });
+
+    function mkElement(id: string): HTMLAudioElement {
+        const el = document.createElement('audio');
+        el.id = id;
+        document.body.appendChild(el);
+        return el;
+    }
+
+    function cleanup(el: HTMLAudioElement): void {
+        document.body.removeChild(el);
+    }
+
+    it('logs a structured error (with element id) for error-class events', () => {
+        const el = mkElement('ringAudio');
+        el.addEventListener('error', handleEvent);
+        el.dispatchEvent(new Event('error'));
+
+        expect(errorSpy).toHaveBeenCalledTimes(1);
+        const [msg] = errorSpy.mock.calls[0] as unknown as Array<string>;
+        expect(msg).toContain('ringAudio');
+        cleanup(el);
+    });
+
+    it('logs all known error-class events', () => {
+        const el = mkElement('ringAudio');
+        for (const type of MEDIA_ERROR_EVENTS) {
+            el.addEventListener(type, handleEvent);
+        }
+        for (const type of MEDIA_ERROR_EVENTS) {
+            errorSpy.mockClear();
+            el.dispatchEvent(new Event(type));
+            expect(errorSpy).toHaveBeenCalledTimes(1);
+        }
+        cleanup(el);
+    });
+
+    it('logs debug-class events only when the debug setting is enabled', () => {
+        const el = mkElement('ringbackAudio');
+        for (const type of MEDIA_DEBUG_EVENTS) {
+            el.addEventListener(type, handleEvent);
+        }
+
+        // setting enabled (default in beforeEach)
+        el.dispatchEvent(new Event('play'));
+        expect(debugSpy).toHaveBeenCalledTimes(1);
+        expect(String(debugSpy.mock.calls[0][0])).toContain('ringbackAudio');
+
+        // setting disabled
+        jest.spyOn(SettingsStore, 'getValue').mockReturnValue(false);
+        debugSpy.mockClear();
+        el.dispatchEvent(new Event('pause'));
+        expect(debugSpy).not.toHaveBeenCalled();
+        cleanup(el);
+    });
+
+    it('ignores events it does not know about', () => {
+        const el = mkElement('callendAudio');
+        el.addEventListener('my-custom-event', handleEvent);
+        el.dispatchEvent(new Event('my-custom-event'));
+
+        expect(errorSpy).not.toHaveBeenCalled();
+        expect(debugSpy).not.toHaveBeenCalled();
+        cleanup(el);
+    });
+
+    it('works when invoked directly with the event target set', () => {
+        const el = mkElement('busyAudio');
+        const e = new Event('error');
+        Object.defineProperty(e, 'target', { value: el });
+
+        handleEvent(e);
+
+        expect(errorSpy).toHaveBeenCalledTimes(1);
+        expect(String(errorSpy.mock.calls[0][0])).toContain('busyAudio');
+        cleanup(el);
+    });
+
+    it('works when bound to an element explicitly', () => {
+        const el = mkElement('busyAudio');
+        handleEvent.call(el, new Event('error'));
+
+        expect(errorSpy).toHaveBeenCalledTimes(1);
+        expect(String(errorSpy.mock.calls[0][0])).toContain('busyAudio');
+        cleanup(el);
+    });
+});

