+
+import { MatrixClient, MatrixEvent, RelationType } from "matrix-js-sdk/src/matrix";
+import { Room } from "matrix-js-sdk/src/models/room";
+import { TypedEventEmitter } from "matrix-js-sdk/src/models/typed-event-emitter";
+
+import {
+    VoiceBroadcastInfoEventContent,
+    VoiceBroadcastInfoEventType,
+    VoiceBroadcastInfoState,
+} from "..";
+
+export enum VoiceBroadcastRecordingEvent {
+    StateChanged = "VoiceBroadcastRecordingEvent.StateChanged",
+}
+
+export type VoiceBroadcastRecordingEventHandlerMap = {
+    [VoiceBroadcastRecordingEvent.StateChanged]: () => void;
+};
+
+/**
+ * Represents a single voice broadcast recording, managing its lifecycle and state.
+ *
+ * The state is initialized by inspecting the related voice broadcast info events in the
+ * room state, and `VoiceBroadcastRecordingEvent.StateChanged` is emitted whenever the
+ * state changes.
+ */
+export class VoiceBroadcastRecording extends TypedEventEmitter<
+    VoiceBroadcastRecordingEvent,
+    VoiceBroadcastRecordingEventHandlerMap
+> {
+    private _state: VoiceBroadcastInfoState;
+
+    public constructor(
+        private matrixClient: MatrixClient,
+        private infoEvent: MatrixEvent,
+        initialState: VoiceBroadcastInfoState,
+    ) {
+        super();
+
+        this._state = this.getInitialState(initialState);
+    }
+
+    public getRoomId(): string {
+        return this.infoEvent.getRoomId();
+    }
+
+    public getId(): string {
+        return this.infoEvent.getId();
+    }
+
+    public get state(): VoiceBroadcastInfoState {
+        return this._state;
+    }
+
+    /**
+     * Stops the voice broadcast recording by sending a `VoiceBroadcastInfoState.Stopped`
+     * state event to the room, referencing the original info event.
+     */
+    public async stop(): Promise<void> {
+        const content: VoiceBroadcastInfoEventContent = {
+            state: VoiceBroadcastInfoState.Stopped,
+            ["m.relates_to"]: {
+                rel_type: RelationType.Reference,
+                event_id: this.getId(),
+            },
+        };
+
+        await this.matrixClient.sendStateEvent(
+            this.getRoomId(),
+            VoiceBroadcastInfoEventType,
+            content,
+            this.matrixClient.getUserId(),
+        );
+
+        this._state = VoiceBroadcastInfoState.Stopped;
+        this.emit(VoiceBroadcastRecordingEvent.StateChanged);
+    }
+
+    /**
+     * Determines the initial state by inspecting the related events in the room state.
+     *
+     * If a related event reports the broadcast as stopped, the recording is stopped;
+     * otherwise the given initial state is used.
+     */
+    private getInitialState(initialState: VoiceBroadcastInfoState): VoiceBroadcastInfoState {
+        const room = this.matrixClient.getRoom(this.getRoomId());
+        if (!room) return initialState;
+
+        const relatedEvents = this.getRelatedStateEvents(room);
+        const isStopped = relatedEvents.some(
+            (event) => event.getContent<VoiceBroadcastInfoEventContent>()?.state === VoiceBroadcastInfoState.Stopped,
+        );
+
+        return isStopped ? VoiceBroadcastInfoState.Stopped : initialState;
+    }
+
+    /**
+     * Returns the related voice broadcast info events found in the room state and the
+     * unfiltered timeline, i.e. events for the same state key or events relating to
+     * the info event.
+     */
+    private getRelatedStateEvents(room: Room): MatrixEvent[] {
+        const events = [
+            ...(room.currentState.getStateEvents(VoiceBroadcastInfoEventType) ?? []),
+            ...this.getUnfilteredTimelineEvents(room),
+        ];
+
+        const seen = new Set<string>();
+        return events.filter((event) => {
+            if (seen.has(event.getId())) return false;
+            seen.add(event.getId());
+
+            const relatesTo = event.getContent<VoiceBroadcastInfoEventContent>()?.["m.relates_to"]?.event_id;
+            return (
+                event.getStateKey() === this.infoEvent.getStateKey()
+                || relatesTo === this.getId()
+            );
+        });
+    }
+
+    private getUnfilteredTimelineEvents(room: Room): MatrixEvent[] {
+        const timelineSet = room.getUnfilteredTimelineSet();
+        if (!timelineSet) return [];
+
+        return timelineSet
+            .getLiveTimeline()
+            .getEvents()
+            .filter((event) => event.getType() === VoiceBroadcastInfoEventType);
+    }
+}
