+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import { MatrixClient, MatrixEvent, RoomEvent } from "matrix-js-sdk/src/matrix";
+import { RoomStateEvent } from "matrix-js-sdk/src/models/room-state";
+import { Room } from "matrix-js-sdk/src/models/room";
+
+import {
+    VoiceBroadcastInfoEventContent,
+    VoiceBroadcastInfoEventType,
+    VoiceBroadcastInfoState,
+} from "..";
+import { VoiceBroadcastRecordingsStore } from "../stores";
+
+// The number of samples per chunk used for the voice broadcast recording.
+const DEFAULT_CHUNK_LENGTH = 300;
+
+/**
+ * Starts a new voice broadcast recording.
+ *
+ * Sends the initial `VoiceBroadcastInfoState.Started` state event (including the
+ * `chunk_length` in its content), waits until the event shows up in the room state,
+ * then creates the corresponding `VoiceBroadcastRecording`, sets it as the current
+ * recording in `VoiceBroadcastRecordingsStore.instance` and returns the info event.
+ *
+ * @param client the matrix client to use.
+ * @param roomId the id of the room in which to start the voice broadcast.
+ * @returns a promise resolving to the voice broadcast info event.
+ */
+export async function startNewVoiceBroadcastRecording(
+    client: MatrixClient,
+    roomId: string,
+): Promise<MatrixEvent> {
+    const infoEventContent: VoiceBroadcastInfoEventContent = {
+        state: VoiceBroadcastInfoState.Started,
+        chunk_length: DEFAULT_CHUNK_LENGTH,
+    };
+
+    const response = await client.sendStateEvent(
+        roomId,
+        VoiceBroadcastInfoEventType,
+        infoEventContent,
+        client.getUserId(),
+    );
+    const eventId = (response as { event_id?: string } | undefined)?.event_id;
+
+    const room = client.getRoom(roomId);
+    if (!room) throw new Error(`Room ${roomId} not found`);
+
+    const infoEvent = await waitForStateEventInRoomState(room, eventId);
+
+    const recording = VoiceBroadcastRecordingsStore.instance.getOrCreateRecording(
+        client,
+        infoEvent,
+        VoiceBroadcastInfoState.Started,
+    );
+    VoiceBroadcastRecordingsStore.instance.setCurrent(recording);
+
+    return infoEvent;
+}
+
+/**
+ * Waits until a voice broadcast info state event shows up in the room state.
+ *
+ * If an `eventId` is given, waits for that specific event; otherwise waits for any
+ * new event of the voice broadcast info type.
+ */
+function waitForStateEventInRoomState(room: Room, eventId?: string): Promise<MatrixEvent> {
+    const knownEventIds = new Set<string>(
+        (room.currentState.getStateEvents(VoiceBroadcastInfoEventType) ?? []).map((e) => e.getId()),
+    );
+
+    return new Promise<MatrixEvent>((resolve) => {
+        let settled = false;
+        let pollTimer: ReturnType<typeof setInterval> | null = null;
+
+        const stopPolling = (): void => {
+            if (pollTimer !== null) {
+                clearInterval(pollTimer);
+                pollTimer = null;
+            }
+        };
+
+        const check = (): void => {
+            if (settled) return;
+
+            const stateEvents = room.currentState.getStateEvents(VoiceBroadcastInfoEventType) ?? [];
+            const event = stateEvents.find((e) => (eventId ? e.getId() === eventId : !knownEventIds.has(e.getId())));
+
+            if (event) {
+                settled = true;
+                room.removeListener(RoomEvent.LocalEchoUpdated, check);
+                room.currentState.off(RoomStateEvent.Events, check);
+                stopPolling();
+                resolve(event);
+            }
+        };
+
+        room.on(RoomEvent.LocalEchoUpdated, check);
+        room.currentState.on(RoomStateEvent.Events, check);
+        pollTimer = setInterval(check, 50);
+        check();
+    });
+}

