diff --git a/internal/server/auth/http.go b/internal/server/auth/http.go
index e112a1c9..0a1ac792 100644
--- a/internal/server/auth/http.go
+++ b/internal/server/auth/http.go
@@ -1,8 +1,13 @@
 package auth

 import (
+	"context"
 	"net/http"

+	"github.com/grpc-ecosystem/grpc-gateway/v2/runtime"
+	"google.golang.org/grpc/codes"
+	"google.golang.org/grpc/status"
+
 	"go.flipt.io/flipt/internal/config"
 )

@@ -47,3 +52,38 @@ func (m Middleware) Handler(next http.Handler) http.Handler {
 		next.ServeHTTP(w, r)
 	})
 }
+
+// ErrorHandler is a grpc-gateway error handler used to intercept errors produced by
+// the auth gateway handler. When an unauthenticated error is returned for a request
+// which contained a client token cookie, the relevant authentication cookies are
+// cleared in the response.
+// Clearing the cookies instructs the client to stop reusing an expired or otherwise
+// invalid token, allowing the client to re-authenticate or fall back to an
+// alternative authentication method.
+// The cookies are cleared prior to the final error response being written so that
+// the client receives both the error status and the cookie invalidation instructions.
+// The standard error response is produced by delegating to the default runtime
+// error handler.
+func (m Middleware) ErrorHandler(ctx context.Context, sm *runtime.ServeMux, ms runtime.Marshaler, w http.ResponseWriter, r *http.Request, err error) {
+	if s, ok := status.FromError(err); ok && s.Code() == codes.Unauthenticated {
+		// only clear the cookies if the client actually used a
+		// cookie-based token for this request
+		if _, cookieErr := r.Cookie(tokenCookieKey); cookieErr == nil {
+			for _, cookieName := range []string{stateCookieKey, tokenCookieKey} {
+				cookie := &http.Cookie{
+					Name:   cookieName,
+					Value:  "",
+					Domain: m.config.Domain,
+					Path:   "/",
+					MaxAge: -1,
+				}
+
+				http.SetCookie(w, cookie)
+			}
+		}
+	}
+
+	// delegate to the default error handler to ensure the standard
+	// error response is written to the client
+	runtime.DefaultHTTPErrorHandler(ctx, sm, ms, w, r, err)
+}

diff --git a/internal/server/authz/authz.go b/internal/server/authz/authz.go
index 54de449c..c330238a 100644
--- a/internal/server/authz/authz.go
+++ b/internal/server/authz/authz.go
@@ -2,7 +2,36 @@ package authz

 import "context"

+type contextKey string
+
+// NamespacesKey is the context key used to store and retrieve
+// the list of namespaces accessible to the authenticated user.
+// It is set by the authorization middleware when a ListNamespaces
+// request is evaluated and consumed by service handlers (e.g.
+// the ListNamespaces endpoint) to filter the namespaces returned.
+const NamespacesKey contextKey = "namespaces"
+
+// Verifier is the interface implemented by authorization engines.
 type Verifier interface {
+	// IsAllowed evaluates whether the request described by input is allowed.
 	IsAllowed(ctx context.Context, input map[string]any) (bool, error)
+	// Namespaces evaluates the list of namespaces accessible to the
+	// authenticated subject described by input.
+	Namespaces(ctx context.Context, input map[string]any) ([]string, error)
+	// Shutdown gracefully stops the verifier releasing any resources.
 	Shutdown(ctx context.Context) error
 }
+
+// ContextNamespaces returns the accessible namespaces stored on the
+// provided context, if any. It returns nil when no accessible
+// namespaces have been stored on the context.
+func ContextNamespaces(ctx context.Context) []string {
+	namespaces, _ := ctx.Value(NamespacesKey).([]string)
+	return namespaces
+}
+
+// WithContextNamespaces returns a copy of the provided context with
+// the accessible namespaces stored on it.
+func WithContextNamespaces(ctx context.Context, namespaces []string) context.Context {
+	return context.WithValue(ctx, NamespacesKey, namespaces)
+}
