+++ b/internal/server/authz/engine/bundle/engine.go
@@ -2,6 +2,8 @@ package bundle

 import (
 	"context"
+	"errors"
+	"fmt"
 	"os"
 	"strings"

@@ -84,6 +86,55 @@ func (e *Engine) IsAllowed(ctx context.Context, input map[string]interface{}) (b
 	return allow, nil
 }

+var (
+	// errNoViewableNamespaces is returned when the evaluated policy
+	// does not define any viewable namespaces (either the decision
+	// path is not defined or it evaluates to an empty result).
+	errNoViewableNamespaces = errors.New("no viewable namespaces defined")
+)
+
+// Namespaces evaluates the viewable namespaces for the authenticated
+// subject described by input using the "flipt/authz/v1/viewable_namespaces"
+// decision path and returns the resulting list of namespace keys.
+func (e *Engine) Namespaces(ctx context.Context, input map[string]interface{}) ([]string, error) {
+	e.logger.Debug("evaluating viewable namespaces", zap.Any("input", input))
+	dec, err := e.opa.Decision(ctx, sdk.DecisionOptions{
+		Path:  "flipt/authz/v1/viewable_namespaces",
+		Input: input,
+	})
+
+	if err != nil {
+		return nil, err
+	}
+
+	return namespacesFromValue(dec.Result)
+}
+
+// namespacesFromValue converts an OPA decision result into a list of
+// namespace keys. An appropriate error is returned when the result is
+// undefined (no viewable namespaces are defined) or malformed.
+func namespacesFromValue(value any) ([]string, error) {
+	if value == nil {
+		return nil, errNoViewableNamespaces
+	}
+
+	values, ok := value.([]any)
+	if !ok {
+		return nil, fmt.Errorf("viewable_namespaces: expected array, got %T", value)
