+
+// Namespaces evaluates the viewable namespaces for the authenticated
+// subject described by input by executing the
+// "data.flipt.authz.v1.viewable_namespaces" query and returns the
+// resulting list of namespace keys.
+func (e *Engine) Namespaces(ctx context.Context, input map[string]interface{}) ([]string, error) {
+	e.mu.RLock()
+	defer e.mu.RUnlock()
+
+	e.logger.Debug("evaluating viewable namespaces", zap.Any("input", input))
+	results, err := e.namespacesQuery.Eval(ctx, rego.EvalInput(input))
+	if err != nil {
+		return nil, err
+	}
+
+	if len(results) == 0 {
+		return nil, errNoViewableNamespaces
+	}
+
+	return namespacesFromValue(results[0].Expressions[0].Value)
+}
+
+// namespacesFromValue converts an OPA evaluation result into a list of
+// namespace keys. An appropriate error is returned when the result is
+// undefined (no viewable namespaces are defined) or malformed.
+func namespacesFromValue(value any) ([]string, error) {
+	if value == nil {
+		return nil, errNoViewableNamespaces
+	}
+
+	switch v := value.(type) {
+	case ast.Set:
+		terms := v.Slice()
+		namespaces := make([]string, 0, len(terms))
+		for _, term := range terms {
+			s, ok := term.Value.(ast.String)
+			if !ok {
+				return nil, fmt.Errorf("viewable_namespaces: expected string, got %T", term.Value)
+			}
+			namespaces = append(namespaces, string(s))
+		}
+		return namespaces, nil
+	case []any:
+		namespaces := make([]string, 0, len(v))
+		for _, item := range v {
+			ns, ok := item.(string)
+			if !ok {
+				return nil, fmt.Errorf("viewable_namespaces: expected string, got %T", item)
+			}
+			namespaces = append(namespaces, ns)
+		}
+		return namespaces, nil
+	default:
+		return nil, fmt.Errorf("viewable_namespaces: expected set or array, got %T", value)
+	}
+}
