+func TestAuthorizationRequiredInterceptor_ListNamespaces(t *testing.T) {
+	var tests = []struct {
+		name              string
+		authn             *authrpc.Authentication
+		validatorAllowed  bool
+		namespaces        []string
+		namespacesWantErr error
+		wantAllowed       bool
+		wantNamespaces    []string
+	}{
+		{
+			name:           "allowed with viewable namespaces",
+			authn:          adminAuth,
+			namespaces:     []string{"default", "foo"},
+			wantAllowed:    true,
+			wantNamespaces: []string{"default", "foo"},
+		},
+		{
+			name:  "allowed without default namespace",
+			authn: adminAuth,
+			// the mock verifier denies IsAllowed to prove that the
+			// ListNamespaces request is authorized via the viewable
+			// namespaces evaluation only
+			validatorAllowed: false,
+			namespaces:       []string{"foo"},
+			wantAllowed:      true,
+			wantNamespaces:   []string{"foo"},
+		},
+		{
+			name:           "allowed with empty viewable namespaces",
+			authn:          adminAuth,
+			namespaces:     []string{},
+			wantAllowed:    true,
+			wantNamespaces: []string{},
+		},
+		{
+			name:              "not allowed when viewable namespaces evaluation fails",
+			authn:             adminAuth,
+			namespacesWantErr: errors.New("no viewable namespaces defined"),
+			wantAllowed:       false,
+		},
+		{
+			name:        "not allowed when unauthenticated",
+			wantAllowed: false,
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+
+			var (
+				logger     = zap.NewNop()
+				allowed    = false
+				handlerCtx context.Context
+
+				ctx     = authmiddlewaregrpc.ContextWithAuthentication(context.Background(), tt.authn)
+				handler = func(ctx context.Context, req interface{}) (interface{}, error) {
+					allowed = true
+					handlerCtx = ctx
+					return nil, nil
+				}
+
+				srv            = &grpc.UnaryServerInfo{Server: &mockServer{}}
+				policyVerifier = &mockPolicyVerifier{
+					isAllowed:         tt.validatorAllowed,
+					namespaces:        tt.namespaces,
+					namespacesWantErr: tt.namespacesWantErr,
+				}
+			)
+
+			_, err := AuthorizationRequiredInterceptor(logger, policyVerifier)(ctx, &flipt.ListNamespaceRequest{}, srv, handler)
+
+			require.Equal(t, tt.wantAllowed, allowed)
+
+			if !tt.wantAllowed {
+				require.Error(t, err)
+				return
+			}
+
+			require.NoError(t, err)
+			require.NotNil(t, handlerCtx)
