+
+			// the viewable namespaces evaluation is performed against
+			// the list namespaces request and the requester authentication
+			require.NotNil(t, policyVerifier.namespacesInput)
+			assert.Equal(t, flipt.Request{
+				Resource: flipt.ResourceNamespace,
+				Action:   flipt.ActionRead,
+				Status:   flipt.StatusSuccess,
+			}, policyVerifier.namespacesInput["request"])
