+// DatabaseProtocol represents the type of database protocol
+type DatabaseProtocol uint8
+
+func (p DatabaseProtocol) String() string {
+	return protocolToString[p]
+}
+
+const (
+	_ DatabaseProtocol = iota
+	// SQLite
+	SQLite
+	// Postgres
+	Postgres
+	// MySQL
+	MySQL
+)
+
+var (
+	protocolToString = map[DatabaseProtocol]string{
+		SQLite:   "sqlite3",
+		Postgres: "postgres",
+		MySQL:    "mysql",
+	}
+
+	stringToProtocol = map[string]DatabaseProtocol{
+		"sqlite3":  SQLite,
+		"postgres": Postgres,
+		"mysql":    MySQL,
+	}
+)
+
+// DSN returns the data source name (connection string) for the database.
+// If a URL is provided it takes precedence over the individual fields,
+// otherwise the connection string is built from the individual fields
+// applying engine-specific defaults where appropriate.
+func (c *DatabaseConfig) DSN() (string, error) {
+	if c.URL != "" {
+		return c.URL, nil
+	}
+
+	if c.Protocol == 0 {
+		return "", errors.New("db.protocol cannot be empty")
+	}
+
+	if _, ok := protocolToString[c.Protocol]; !ok {
+		return "", fmt.Errorf("invalid db.protocol: %d (expected: sqlite3, postgres, mysql)", c.Protocol)
+	}
+
+	if c.Name == "" {
+		return "", errors.New("db.name cannot be empty")
+	}
+
+	switch c.Protocol {
+	case SQLite:
+		return fmt.Sprintf("file:%s", c.Name), nil
+
+	case Postgres:
+		if c.Host == "" {
+			return "", errors.New("db.host cannot be empty")
+		}
+
+		port := c.Port
+		if port == 0 {
+			port = 5432
+		}
+
+		return fmt.Sprintf("postgres://%s%s@%s:***@%s:%d/%s", c.User, c.password(), c.Host, port, c.Name), nil
+
+	case MySQL:
+		if c.Host == "" {
+			return "", errors.New("db.host cannot be empty")
+		}
+
+		port := c.Port
+		if port == 0 {
+			port = 3306
