+
+func TestSyslogSeverityDerivedScore(t *testing.T) {
+	config.Conf = config.Config{}
+	result := models.ScanResult{
+		ServerName: "sev01",
+		Family:     "debian",
+		Release:    "10",
+		ScannedCves: models.VulnInfos{
+			"CVE-2020-1000": {
+				CveID: "CVE-2020-1000",
+				AffectedPackages: models.PackageFixStatuses{
+					{Name: "pkg1"},
+				},
+				CveContents: models.CveContents{
+					models.DebianSecurityTracker: {
+						Type:          models.DebianSecurityTracker,
+						Cvss2Severity: "high",
+						Cvss3Severity: "high",
+					},
+				},
+			},
+		},
+	}
+	messages := SyslogWriter{}.encodeSyslog(result)
+	if len(messages) != 1 {
+		t.Fatalf("expected 1 message, actual: %d", len(messages))
+	}
+	m := messages[0]
+	// severity-derived scores must appear exactly like numeric CVSS3 scores
+	for _, expected := range []string{
+		`cvss_score_debian_security_tracker_v2="8.90"`,
+		`cvss_score_debian_security_tracker_v3="8.90"`,
+	} {
+		if !strings.Contains(m, expected) {
+			t.Errorf("expected message to contain %q, actual: %s", expected, m)
+		}
+	}
+}
+
+func TestTuiSummaryLinesSeverityDerived(t *testing.T) {
+	config.Conf = config.Config{}
+	currentScanResult = models.ScanResult{
+		ServerName: "sev02",
+		Family:     "trivy",
+		Release:    "1",
+		ScannedCves: models.VulnInfos{
+			"CVE-2020-2000": {
+				CveID: "CVE-2020-2000",
+				AffectedPackages: models.PackageFixStatuses{
+					{Name: "libfoo"},
+				},
+				CveContents: models.CveContents{
+					models.Trivy: {
+						Type:          models.Trivy,
+						Cvss3Severity: "HIGH",
+						Summary:       "some summary",
+					},
+				},
+			},
+		},
+	}
+	s := summaryLines(currentScanResult)
+	if !strings.Contains(s, "|  8.9 |") {
+		t.Errorf("expected summary to show derived score 8.9, actual: %s", s)
+	}
+}
+
+func TestTuiDetailLinesSeverityDerived(t *testing.T) {
+	config.Conf = config.Config{}
+	currentScanResult = models.ScanResult{
+		ServerName: "sev03",
+		Family:     "trivy",
+		Release:    "1",
+		ScannedCves: models.VulnInfos{
+			"CVE-2020-3000": {
+				CveID: "CVE-2020-3000",
+				AffectedPackages: models.PackageFixStatuses{
+					{Name: "libbar"},
+				},
+				CveContents: models.CveContents{
+					models.Trivy: {
+						Type:          models.Trivy,
+						Cvss3Severity: "HIGH",
+						Summary:       "some summary",
+					},
+				},
+			},
+		},
+	}
+	vinfos = currentScanResult.ScannedCves.ToSortedSlice()
+	currentVinfo = 0
+	text, err := detailLines()
+	if err != nil {
+		t.Fatalf("err: %s", err)
+	}
+	// the derived score must be displayed like a real numeric score
+	if !strings.Contains(text, "8.9/-") {
+		t.Errorf("expected detail lines to show derived score 8.9/-, actual:\n%s", text)
+	}
+}
+
+func TestSlackAttachmentTextSeverityDerived(t *testing.T) {
+	config.Conf = config.Config{}
+	vinfo := models.VulnInfo{
+		CveID: "CVE-2020-4000",
+		AffectedPackages: models.PackageFixStatuses{
+			{Name: "libbaz"},
+		},
+		CveContents: models.CveContents{
+			models.Trivy: {
+				Type:          models.Trivy,
+				Cvss3Severity: "HIGH",
+				Summary:       "some summary",
+			},
+		},
+	}
+	text := attachmentText(vinfo, "trivy", nil, models.Packages{})
+	if !strings.Contains(text, "* 8.9 (HIGH)*") {
+		t.Errorf("expected slack text to show derived score, actual:\n%s", text)
+	}
