+
+func TestPackage_HasPortScanSuccessOn(t *testing.T) {
+	cases := []struct {
+		name     string
+		pack     Package
+		expected bool
+	}{
+		{
+			name:     "no affected processes",
+			pack:     Package{Name: "nginx"},
+			expected: false,
+		},
+		{
+			name: "affected process without listen ports",
+			pack: Package{
+				Name: "nginx",
+				AffectedProcs: []AffectedProcess{
+					{PID: "1", Name: "nginx"},
+				},
+			},
+			expected: false,
+		},
+		{
+			name: "listen port without successful scan",
+			pack: Package{
+				Name: "nginx",
+				AffectedProcs: []AffectedProcess{
+					{
+						PID:  "1",
+						Name: "nginx",
+						ListenPorts: []ListenPort{
+							{Address: "*", Port: "80", PortScanSuccessOn: []string{}},
+						},
+					},
+				},
+			},
+			expected: false,
+		},
+		{
+			name: "listen port with successful scan",
+			pack: Package{
+				Name: "nginx",
+				AffectedProcs: []AffectedProcess{
+					{
+						PID:  "1",
+						Name: "nginx",
+						ListenPorts: []ListenPort{
+							{
+								Address:           "*",
+								Port:              "80",
+								PortScanSuccessOn: []string{"192.168.0.1"},
+							},
+						},
+					},
+				},
+			},
+			expected: true,
+		},
+	}
+
+	for _, c := range cases {
+		actual := c.pack.HasPortScanSuccessOn()
+		if actual != c.expected {
+			t.Errorf("%s: HasPortScanSuccessOn() = %v, want %v",
+				c.name, actual, c.expected)
+		}
+	}
+}
+
+func TestListenPorts_String(t *testing.T) {
+	cases := []struct {
+		name     string
+		in       ListenPorts
+		expected string
+	}{
+		{
+			name:     "empty",
+			in:       ListenPorts{},
+			expected: "[]",
+		},
+		{
+			name:     "nil",
+			in:       nil,
+			expected: "[]",
+		},
+		{
+			name: "one port without success",
+			in: ListenPorts{
+				{Address: "127.0.0.1", Port: "22"},
+			},
+			expected: "127.0.0.1:22",
+		},
+		{
+			name: "one wildcard port with success",
+			in: ListenPorts{
+				{
+					Address:           "*",
+					Port:              "80",
+					PortScanSuccessOn: []string{"192.168.0.10", "192.168.0.11"},
+				},
+			},
+			expected: "*:80(◉ Scannable: [192.168.0.10 192.168.0.11])",
+		},
+		{
+			name: "ipv6 port with success",
+			in: ListenPorts{
+				{
+					Address:           "[::1]",
+					Port:              "443",
+					PortScanSuccessOn: []string{"192.168.0.10"},
+				},
+			},
+			expected: "[::1]:443(◉ Scannable: [192.168.0.10])",
+		},
+		{
+			name: "multiple ports",
+			in: ListenPorts{
+				{Address: "127.0.0.1", Port: "22"},
+				{
+					Address:           "*",
+					Port:              "80",
+					PortScanSuccessOn: []string{"192.168.0.10"},
+				},
+			},
+			expected: "127.0.0.1:22, *:80(◉ Scannable: [192.168.0.10])",
+		},
+	}
+
+	for _, c := range cases {
+		actual := c.in.String()
