+
+func TestListenPort_JSON(t *testing.T) {
+	pack := Package{
+		Name: "nginx",
+		AffectedProcs: []AffectedProcess{
+			{
+				PID:  "1",
+				Name: "nginx",
+				ListenPorts: []ListenPort{
+					{
+						Address:           "*",
+						Port:              "80",
+						PortScanSuccessOn: []string{"192.168.0.10"},
+					},
+				},
+			},
+		},
+	}
+
+	expected := `{"name":"nginx","version":"","release":"","newVersion":"","newRelease":"","arch":"","repository":"","changelog":{"contents":"","method":""},"AffectedProcs":[{"pid":"1","name":"nginx","listenPorts":[{"address":"*","port":"80","portScanSuccessOn":["192.168.0.10"]}]}]}`
+
+	t.Run("marshal", func(t *testing.T) {
+		actual := mustMarshal(t, pack)
+		if actual != expected {
+			t.Errorf("marshal:\n got %s\nwant %s", actual, expected)
+		}
+	})
+
+	t.Run("unmarshal", func(t *testing.T) {
+		var got Package
+		if err := json.Unmarshal([]byte(expected), &got); err != nil {
+			t.Fatalf("unmarshal: %s", err)
+		}
+		if !reflect.DeepEqual(pack, got) {
+			t.Errorf("unmarshal roundtrip:\n got %#v\nwant %#v", got, pack)
+		}
+	})
+}
+
+func mustMarshal(t *testing.T, v interface{}) string {
+	t.Helper()
+	b, err := json.Marshal(v)
+	if err != nil {
+		t.Fatalf("marshal: %s", err)
+	}
+	return string(b)
+}
