+func newBaseForPortScan(ipv4s []string, packs models.Packages) *base {
+	return &base{
+		ServerInfo: config.ServerInfo{
+			IPv4Addrs: ipv4s,
+		},
+		osPackages: osPackages{
+			Packages: packs,
+		},
+	}
+}
+
+func TestBase_parseListenPorts(t *testing.T) {
+	cases := []struct {
+		in       string
+		expected models.ListenPort
+	}{
+		{
+			in:       "127.0.0.1:22",
+			expected: models.ListenPort{Address: "127.0.0.1", Port: "22"},
+		},
+		{
+			in:       "*:80",
+			expected: models.ListenPort{Address: "*", Port: "80"},
+		},
+		{
+			in:       "[::1]:443",
+			expected: models.ListenPort{Address: "[::1]", Port: "443"},
+		},
+		{
+			in:       "0.0.0.0:0",
+			expected: models.ListenPort{Address: "0.0.0.0", Port: "0"},
+		},
+		{
+			// the last colon separates the address and the port,
+			// so the brackets of an IPv6 address are preserved
+			in:       "[fe80::1234]:8080",
+			expected: models.ListenPort{Address: "[fe80::1234]", Port: "8080"},
+		},
+	}
+
+	l := newBaseForPortScan(nil, nil)
+	for _, c := range cases {
+		actual := l.parseListenPorts(c.in)
+		if !reflect.DeepEqual(c.expected, actual) {
+			t.Errorf("parseListenPorts(%s) = %#v, want %#v", c.in, actual, c.expected)
+		}
+	}
+}
+
+func TestBase_detectScanDest(t *testing.T) {
+	packs := models.Packages{
+		"nginx": {
+			Name: "nginx",
+			AffectedProcs: []models.AffectedProcess{
+				{
+					PID:  "100",
+					Name: "nginx",
+					ListenPorts: []models.ListenPort{
+						{Address: "*", Port: "80"},
+						{Address: "127.0.0.1", Port: "22"},
+						{Address: "[::1]", Port: "443"},
+					},
+				},
+			},
+		},
+		// the same wildcard port is detected on another package too,
+		// it must not be duplicated in the scan destinations
+		"other": {
+			Name: "other",
+			AffectedProcs: []models.AffectedProcess{
+				{
+					PID:  "200",
+					Name: "other",
+					ListenPorts: []models.ListenPort{
+						{Address: "*", Port: "80"},
+						{Address: "192.168.0.10", Port: "443"},
+					},
+				},
+			},
+		},
+		// a package without affected processes
+		"plain": {
+			Name: "plain",
+		},
+	}
+
+	l := newBaseForPortScan(
+		[]string{"192.168.0.10", "192.168.0.11"}, packs)
+
+	expected := []string{
+		"127.0.0.1:22",
+		"192.168.0.10:443",
+		"192.168.0.10:80",
+		"192.168.0.11:80",
+		"[::1]:443",
+	}
+	actual := l.detectScanDest()
+	if !reflect.DeepEqual(expected, actual) {
+		t.Errorf("detectScanDest() = %#v, want %#v", actual, expected)
+	}
+
+	// no affected processes -> empty (non-nil) slice
+	empty := newBaseForPortScan(nil, models.Packages{
+		"plain": {Name: "plain"},
+	})
+	got := empty.detectScanDest()
+	if len(got) != 0 {
+		t.Errorf("detectScanDest() = %#v, want empty", got)
+	}
+
+	// deterministic: repeated calls return the same order
+	for i := 0; i < 20; i++ {
+		if !reflect.DeepEqual(expected, l.detectScanDest()) {
+			t.Fatalf("detectScanDest() is not deterministic")
+		}
+	}
+}
