+func TestBase_findPortScanSuccessOn(t *testing.T) {
+	l := newBaseForPortScan(
+		[]string{"192.168.0.10", "192.168.0.11"}, nil)
+
+	successIPPorts := []string{
+		"192.168.0.10:80",
+		"192.168.0.11:80",
+		"127.0.0.1:22",
+	}
+
+	cases := []struct {
+		name     string
+		search   models.ListenPort
+		expected []string
+	}{
+		{
+			name:     "wildcard all matched",
+			search:   models.ListenPort{Address: "*", Port: "80"},
+			expected: []string{"192.168.0.10", "192.168.0.11"},
+		},
+		{
+			name:     "wildcard partial matched",
+			search:   models.ListenPort{Address: "*", Port: "80"},
+			expected: []string{"192.168.0.10", "192.168.0.11"},
+		},
+		{
+			name:     "wildcard no match",
+			search:   models.ListenPort{Address: "*", Port: "443"},
+			expected: []string{},
+		},
+		{
+			name:     "concrete matched",
+			search:   models.ListenPort{Address: "192.168.0.11", Port: "80"},
+			expected: []string{"192.168.0.11"},
+		},
+		{
+			name:     "concrete exact match only",
+			search:   models.ListenPort{Address: "192.168.0.12", Port: "80"},
+			expected: []string{},
+		},
+		{
+			name:     "concrete loopback matched",
+			search:   models.ListenPort{Address: "127.0.0.1", Port: "22"},
+			expected: []string{"127.0.0.1"},
+		},
+		{
+			name:     "ipv6 literal is not recorded",
+			search:   models.ListenPort{Address: "[::1]", Port: "443"},
+			expected: []string{},
+		},
+	}
+
+	for _, c := range cases {
+		actual := l.findPortScanSuccessOn(successIPPorts, c.search)
+		if actual == nil {
+			t.Errorf("%s: findPortScanSuccessOn() must not return nil", c.name)
+			continue
+		}
+		if !reflect.DeepEqual(c.expected, actual) {
+			t.Errorf("%s: findPortScanSuccessOn() = %#v, want %#v",
+				c.name, actual, c.expected)
+		}
+	}
+
+	// deduplication of addresses
+	dup := newBaseForPortScan(
+		[]string{"192.168.0.10", "192.168.0.10", "192.168.0.11"}, nil)
+	got := dup.findPortScanSuccessOn(
+		[]string{"192.168.0.10:80", "192.168.0.10:80", "192.168.0.11:80"},
+		models.ListenPort{Address: "*", Port: "80"})
+	if !reflect.DeepEqual([]string{"192.168.0.10", "192.168.0.11"}, got) {
+		t.Errorf("dedup: findPortScanSuccessOn() = %#v, want [192.168.0.10 192.168.0.11]", got)
+	}
+}
