+func TestBase_scanPorts(t *testing.T) {
+	// a real listening endpoint on 127.0.0.1
+	ln, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		t.Fatalf("failed to listen: %s", err)
+	}
+	defer ln.Close()
+	go func() {
+		for {
+			conn, err := ln.Accept()
+			if err != nil {
+				return
+			}
+			_ = conn.Close()
+		}
+	}()
+	_, openPort, err := net.SplitHostPort(ln.Addr().String())
+	if err != nil {
+		t.Fatalf("failed to split host port: %s", err)
+	}
+
+	packs := models.Packages{
+		"ssh": {
+			Name: "ssh",
+			AffectedProcs: []models.AffectedProcess{
+				{
+					PID:  "1",
+					Name: "sshd",
+					ListenPorts: []models.ListenPort{
+						{Address: "127.0.0.1", Port: openPort},
+						{Address: "127.0.0.1", Port: "9"},
+						{Address: "*", Port: "9"},
+					},
+				},
+			},
+		},
+	}
+
+	l := newBaseForPortScan([]string{"127.0.0.1"}, packs)
+	l.scanPorts()
+
+	got := l.Packages["ssh"].AffectedProcs[0].ListenPorts
+	if !reflect.DeepEqual([]string{"127.0.0.1"}, got[0].PortScanSuccessOn) {
+		t.Errorf("open port PortScanSuccessOn = %#v, want [127.0.0.1]",
+			got[0].PortScanSuccessOn)
+	}
+	if got[1].PortScanSuccessOn == nil || len(got[1].PortScanSuccessOn) != 0 {
+		t.Errorf("closed concrete port PortScanSuccessOn = %#v, want []",
+			got[1].PortScanSuccessOn)
+	}
+	if got[2].PortScanSuccessOn == nil || len(got[2].PortScanSuccessOn) != 0 {
+		t.Errorf("closed wildcard port PortScanSuccessOn = %#v, want []",
+			got[2].PortScanSuccessOn)
+	}
+
+	// HasPortScanSuccessOn of the package
+	if !l.Packages["ssh"].HasPortScanSuccessOn() {
+		t.Errorf("ssh package should have a scannable port")
+	}
+}
+
+func TestBase_detectScanDestSortedWithWildcardIPOrder(t *testing.T) {
+	// when expanding "*", the destinations preserve the order of
+	// ServerInfo.IPv4Addrs before the final deterministic sort
+	packs := models.Packages{
+		"nginx": {
+			Name: "nginx",
+			AffectedProcs: []models.AffectedProcess{
+				{
+					PID:  "100",
+					Name: "nginx",
+					ListenPorts: []models.ListenPort{
+						{Address: "*", Port: "80"},
+					},
+				},
+			},
+		},
+	}
+
+	l := newBaseForPortScan([]string{"10.0.0.2", "10.0.0.10"}, packs)
+	got := l.detectScanDest()
+	expected := []string{"10.0.0.10:80", "10.0.0.2:80"}
+	if !reflect.DeepEqual(expected, got) {
+		t.Errorf("detectScanDest() = %#v, want %#v", got, expected)
+	}
+	if !sort.StringsAreSorted(got) {
+		t.Errorf("detectScanDest() = %#v is not sorted", got)
+	}
+}
