+func (c *U2FAuthenticateChallenge) UnmarshalJSON(data []byte) error {
+	var in struct {
+		u2f.AuthenticateChallenge
+		Challenges []u2f.AuthenticateChallenge `json:"challenges"`
+	}
+	if err := json.Unmarshal(data, &in); err != nil {
+		return trace.Wrap(err)
+	}
+	switch {
+	case len(in.Challenges) > 0:
+		c.AuthenticateChallenge = &in.Challenges[0]
+		c.Challenges = in.Challenges
+	case in.Challenge != "":
+		// Legacy single-challenge format.
+		c.AuthenticateChallenge = &in.AuthenticateChallenge
+		c.Challenges = []u2f.AuthenticateChallenge{in.AuthenticateChallenge}
+	}
+	return nil
+}
