+// TestTmpU2FAuthenticateChallengeJSON verifies backward-compatible JSON
+// marshaling/unmarshaling of U2FAuthenticateChallenge.
+func TestTmpU2FAuthenticateChallengeJSON(t *testing.T) {
+	legacy := u2f.AuthenticateChallenge{
+		Version:   "U2F_V2",
+		Challenge: "chal1",
+		KeyHandle: "kh1",
+		AppID:     "https://example.com",
+	}
+	second := u2f.AuthenticateChallenge{
+		Version:   "U2F_V2",
+		Challenge: "chal2",
+		KeyHandle: "kh2",
+		AppID:     "https://example.com",
+	}
+
+	// Multi-device format marshals into a superset of the legacy format.
+	in := &U2FAuthenticateChallenge{
+		AuthenticateChallenge: &legacy,
+		Challenges:            []u2f.AuthenticateChallenge{legacy, second},
+	}
+	raw, err := json.Marshal(in)
+	require.NoError(t, err)
+	t.Logf("marshaled: %s", raw)
+
+	var asMap map[string]interface{}
+	require.NoError(t, json.Unmarshal(raw, &asMap))
+	// Legacy top-level fields are present.
+	require.Equal(t, legacy.Version, asMap["version"])
+	require.Equal(t, legacy.Challenge, asMap["challenge"])
+	require.Equal(t, legacy.KeyHandle, asMap["keyHandle"])
+	require.Equal(t, legacy.AppID, asMap["appId"])
+	// And the legacy format parses into the old client's struct.
+	var oldClientView u2f.AuthenticateChallenge
+	require.NoError(t, json.Unmarshal(raw, &oldClientView))
+	require.Equal(t, legacy, oldClientView)
+	// The challenges array is present.
+	var withChallenges struct {
+		Challenges []u2f.AuthenticateChallenge `json:"challenges"`
+	}
+	require.NoError(t, json.Unmarshal(raw, &withChallenges))
+	require.Equal(t, []u2f.AuthenticateChallenge{legacy, second}, withChallenges.Challenges)
+
+	// Multi-device format round-trips.
+	var roundTripped U2FAuthenticateChallenge
+	require.NoError(t, json.Unmarshal(raw, &roundTripped))
+	require.Equal(t, in.Challenges, roundTripped.Challenges)
+	require.NotNil(t, roundTripped.AuthenticateChallenge)
+	require.Equal(t, legacy, *roundTripped.AuthenticateChallenge)
+
+	// Legacy single-device format (from an older server) is accepted.
+	legacyRaw, err := json.Marshal(legacy)
+	require.NoError(t, err)
+	var fromLegacy U2FAuthenticateChallenge
+	require.NoError(t, json.Unmarshal(legacyRaw, &fromLegacy))
+	require.NotNil(t, fromLegacy.AuthenticateChallenge)
+	require.Equal(t, legacy, *fromLegacy.AuthenticateChallenge)
+	require.Equal(t, []u2f.AuthenticateChallenge{legacy}, fromLegacy.Challenges)
+
+	// A nil receiver marshals to null.
+	var nilC *U2FAuthenticateChallenge
+	raw, err = json.Marshal(nilC)
+	require.NoError(t, err)
+	require.Equal(t, "null", string(raw))
+}
