+// NotifyExit signals the prompt singletons that the program is exiting. It
+// closes the global stdin reader, allowing it to restore the terminal state if
+// a password read was in progress.
+func NotifyExit() {
+	stdinMU.Lock()
+	defer stdinMU.Unlock()
+	if stdin == nil {
+		return
+	}
+	if closer, ok := stdin.(interface{ Close() error }); ok {
+		// Best effort: a failed close must not prevent the program from
+		// exiting.
+		if err := closer.Close(); err != nil {
+			log.WithError(err).Error("prompt: failed to close stdin reader on exit")
+		}
+	}
