+		{Key: "data", Value: strings.Repeat("a", dataSize)},
+		{Key: "$db", Value: "test"},
+	})
+	require.NoError(t, err)
+
+	message := makeTestOpMsgWithBody(t, document)
+
+	// Read it back.
