+			payloadLength: 0,
+			want:          0,
+		},
+		{
+			name:          "payload smaller than the default maximum message size",
+			payloadLength: defaultMaxMessageSizeBytes - 1,
+			want:          defaultMaxMessageSizeBytes - 1,
+		},
+		{
+			name:          "payload equal to the default maximum message size",
+			payloadLength: defaultMaxMessageSizeBytes,
+			want:          defaultMaxMessageSizeBytes,
+		},
+		{
+			name:          "payload larger than the default maximum message size",
+			payloadLength: defaultMaxMessageSizeBytes + 1,
