+
+package model
+
+import (
+	"sync"
+
+	"github.com/gravitational/trace"
+	"github.com/sashabaranov/go-openai"
+	"github.com/tiktoken-go/tokenizer/codec"
+)
+
+// TokenCount is a struct that tracks the number of tokens used in a single
+// invocation of the agent. It aggregates all prompt and completion token
+// counters accumulated across every step of the invocation.
+type TokenCount struct {
+	promptCounters     TokenCounters
+	completionCounters TokenCounters
+}
+
+// NewTokenCount creates a new, empty TokenCount.
+func NewTokenCount() *TokenCount {
+	return &TokenCount{}
+}
+
+// AddPromptCounter appends a new prompt-side token counter to the TokenCount.
+// Nil counters are ignored.
+func (t *TokenCount) AddPromptCounter(counter TokenCounter) {
+	if counter == nil {
+		return
+	}
+
+	t.promptCounters = append(t.promptCounters, counter)
+}
+
+// AddCompletionCounter appends a new completion-side token counter to the
+// TokenCount. Nil counters are ignored.
+func (t *TokenCount) AddCompletionCounter(counter TokenCounter) {
+	if counter == nil {
+		return
+	}
+
+	t.completionCounters = append(t.completionCounters, counter)
+}
+
+// CountAll returns the total number of prompt and completion tokens used by
+// the invocation, in the order (promptTotal, completionTotal).
+func (t *TokenCount) CountAll() (int, int) {
+	return t.promptCounters.CountAll(), t.completionCounters.CountAll()
+}
+
+// TokenCounter is an interface for a token counter.
+type TokenCounter interface {
+	// TokenCount returns the number of tokens counted.
+	TokenCount() int
+}
+
+// TokenCounters is a slice of TokenCounter.
+type TokenCounters []TokenCounter
+
+// CountAll returns the sum of the token counts of all counters in the slice.
+func (t TokenCounters) CountAll() int {
+	count := 0
+	for _, counter := range t {
+		if counter == nil {
+			continue
+		}
+
+		count += counter.TokenCount()
+	}
+
+	return count
+}
+
+// StaticTokenCounter is a token counter with a fixed, known value. It is used
+// for the prompt tokens and for completed, non-streamed responses.
+type StaticTokenCounter struct {
+	tokenCount int
+}
+
+// TokenCount returns the fixed number of tokens counted.
+func (s *StaticTokenCounter) TokenCount() int {
+	return s.tokenCount
+}
+
+// NewPromptTokenCounter creates a new token counter for the prompt tokens used
+// by a list of messages. The prompt total is the sum over all messages of the
+// per-message and per-role overheads and the number of tokens in the message
+// content, all computed with the cl100k_base tokenizer.
+func NewPromptTokenCounter(messages []openai.ChatCompletionMessage) (*StaticTokenCounter, error) {
+	tokenizer := codec.NewCl100kBase()
+
+	count := 0
+	for _, message := range messages {
+		tokens, _, err := tokenizer.Encode(message.Content)
+		if err != nil {
+			return nil, trace.Wrap(err)
+		}
+
+		count += perMessage + perRole + len(tokens)
+	}
+
+	return &StaticTokenCounter{tokenCount: count}, nil
+}
+
+// NewSynchronousTokenCounter creates a new token counter for the completion
+// tokens used by a full, non-streamed response. The completion total is the
+// per-request overhead plus the number of tokens in the response, computed
+// with the cl100k_base tokenizer.
+func NewSynchronousTokenCounter(completion string) (*StaticTokenCounter, error) {
+	tokens, _, err := codec.NewCl100kBase().Encode(completion)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+
+	return &StaticTokenCounter{tokenCount: perRequest + len(tokens)}, nil
+}
+
+// AsynchronousTokenCounter is a token counter for the completion tokens used
+// by a streamed response. The counter is initialized with the number of tokens
+// in the first streamed fragment and is incremented for every subsequent
+// fragment received from the model.
+type AsynchronousTokenCounter struct {
+	mu         sync.Mutex
+	tokenCount int
+	finished   bool
+}
+
+// Add increments the token count by one. It returns an error if the counter
+// has already been finalized by a call to TokenCount.
+func (a *AsynchronousTokenCounter) Add() error {
+	a.mu.Lock()
+	defer a.mu.Unlock()
+
+	if a.finished {
+		return trace.Errorf("token counter is finished")
+	}
+
+	a.tokenCount++
+	return nil
+}
+
+// TokenCount finalizes the counter and returns the total number of completion
+// tokens used, including the per-request overhead. It is idempotent and
+// non-blocking: once the counter is finalized, any subsequent calls return the
+// same value, and any subsequent calls to Add return an error.
+func (a *AsynchronousTokenCounter) TokenCount() int {
+	a.mu.Lock()
+	defer a.mu.Unlock()
+
+	a.finished = true
+
+	return perRequest + a.tokenCount
+}
+
+// NewAsynchronousTokenCounter creates a new token counter for the completion
+// tokens used by a streamed response. The counter is initialized with the
+// number of tokens in the starting fragment of the streamed completion,
+// computed with the cl100k_base tokenizer.
+func NewAsynchronousTokenCounter(start string) (*AsynchronousTokenCounter, error) {
+	tokens, _, err := codec.NewCl100kBase().Encode(start)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+
+	return &AsynchronousTokenCounter{tokenCount: len(tokens)}, nil
+}
