+func TestTeleportHome(t *testing.T) {
+	// Make sure the default profile directory is clean so we can
+	// verify that no data is written there while TELEPORT_HOME is set.
+	defaultHome := profile.FullProfilePath("")
+	os.RemoveAll(defaultHome)
+	t.Cleanup(func() {
+		os.RemoveAll(defaultHome)
+	})
+
+	// Point tsh at a custom home directory. The redundant trailing
+	// separators verify that the value is normalized with path.Clean.
+	customHome := filepath.Join(t.TempDir(), "home") + "//"
+	os.Setenv("TELEPORT_HOME", customHome)
+	t.Cleanup(func() {
+		os.Unsetenv("TELEPORT_HOME")
+	})
+	cleanedHome := path.Clean(customHome)
+
+	connector := mockConnector(t)
+
+	alice, err := types.NewUser("alice@example.com")
+	require.NoError(t, err)
+	alice.SetRoles([]string{"admin"})
+
+	authProcess, proxyProcess := makeTestServers(t, connector, alice)
+
+	authServer := authProcess.GetAuthServer()
+	require.NotNil(t, authServer)
+
+	proxyAddr, err := proxyProcess.ProxyWebAddr()
+	require.NoError(t, err)
+
+	// Log in with TELEPORT_HOME set: the profile and the keys must be
+	// stored under the custom home directory.
+	err = Run([]string{
+		"login",
+		"--insecure",
+		"--auth", connector.GetName(),
+		"--proxy", proxyAddr.String(),
+	}, cliOption(func(cf *CLIConf) error {
+		cf.mockSSOLogin = mockSSOLogin(t, authServer, alice)
+		return nil
+	}))
+	require.NoError(t, err)
+
+	proxyHost, _, err := net.SplitHostPort(proxyAddr.String())
+	require.NoError(t, err)
+
+	require.FileExists(t, filepath.Join(cleanedHome, proxyHost+".yaml"))
+	require.FileExists(t, filepath.Join(cleanedHome, "current-profile"))
+	require.DirExists(t, filepath.Join(cleanedHome, "keys", proxyHost))
+
+	// Nothing may have been written to the default profile directory.
+	require.NoFileExists(t, filepath.Join(defaultHome, proxyHost+".yaml"))
+	require.NoFileExists(t, filepath.Join(defaultHome, "current-profile"))
