+// migrateEventFieldsMapWithRetry tries the event fields map migration
+// multiple times until it succeeds in the case of spontaneous errors.
+func (l *Log) migrateEventFieldsMapWithRetry(ctx context.Context) {
+	for {
+		err := l.migrateEventFieldsMap(ctx)
+
+		if err == nil {
+			break
+		}
+
+		delay := utils.HalfJitter(time.Minute)
+		log.WithError(err).Errorf("Background event fields map migration failed, retrying in %f seconds", delay.Seconds())
+		select {
+		case <-time.After(delay):
+		case <-ctx.Done():
+			log.WithError(ctx.Err()).Error("Background event fields map migration cancelled")
+			return
+		}
+	}
+}
+
+// migrateEventFieldsMap converts the legacy `Fields` JSON string attribute
+// on all events in the table to the native `FieldsMap` DynamoDB map
+// attribute, which makes individual event fields queryable with DynamoDB
+// expressions.
+//
+// The migration is a no-op once it has completed. Completion is tracked by
+// a flag stored in the cluster backend so that subsequent startups do not
+// need to re-scan the table.
+func (l *Log) migrateEventFieldsMap(ctx context.Context) error {
+	if l.fieldsMapMigrated.Load() {
+		return nil
+	}
+
+	// Acquire a lock so that only one auth server performs the migration
+	// at any given time.
+	return backend.RunWhileLocked(ctx, l.backend, eventFieldsMapMigrationLock, rfd24MigrationLockTTL, func(ctx context.Context) error {
+		// Re-check the migration status now that the lock is held as
+		// another node may have completed the migration since the initial
+		// check.
+		complete, err := l.isEventFieldsMapMigrationComplete(ctx)
+		if err != nil {
+			return trace.Wrap(err)
+		}
+		if complete {
+			return nil
+		}
+
+		if err := l.migrateEventFieldsMapItems(ctx); err != nil {
+			return trace.WrapWithMessage(err, "failed to migrate event fields to the map format")
+		}
+
+		return l.setEventFieldsMapMigrationFlag(ctx)
+	})
+}
+
+// isEventFieldsMapMigrationComplete checks the backend flag indicating
+// that the event fields map migration has completed.
+func (l *Log) isEventFieldsMapMigrationComplete(ctx context.Context) (bool, error) {
+	_, err := l.backend.Get(ctx, eventFieldsMapMigrationFlag)
+	if err != nil {
+		if trace.IsNotFound(err) {
+			return false, nil
+		}
+		return false, trace.Wrap(err)
+	}
+	return true, nil
+}
+
+// setEventFieldsMapMigrationFlag records in the cluster backend that the
+// event fields map migration has completed and switches new events over to
+// the native map format.
+func (l *Log) setEventFieldsMapMigrationFlag(ctx context.Context) error {
+	if _, err := l.backend.Put(ctx, backend.Item{
+		Key:   eventFieldsMapMigrationFlag,
+		Value: []byte("true"),
+	}); err != nil {
+		return trace.WrapWithMessage(err, "failed to set the event fields map migration flag")
+	}
+
+	l.fieldsMapMigrated.Store(true)
+	log.Info("Event fields map migration completed, new events will be written in the map format")
+	return nil
+}
+
+// migrateEventFieldsMapItems walks the events table and converts events
+// that still store their fields in the legacy `Fields` JSON string
+// attribute to the native `FieldsMap` DynamoDB map attribute.
+//
+// This function is not atomic on error but safely interruptible.
+// This means that the function may return an error without having
+// processed all data but no residual temporary or broken data is left and
+// the process can be resumed at any time by running this function again.
+// Events that have already been converted are filtered out of the scan,
+// which is what makes the migration resumable from any interruption point.
+//
+// Invariants:
+// - The eventFieldsMapMigrationLock must be held by the node.
+func (l *Log) migrateEventFieldsMapItems(ctx context.Context) error {
+	log.Info("Starting event fields map migration")
+
+	var startKey map[string]*dynamodb.AttributeValue
+	workerCounter := atomic.NewInt32(0)
+	totalProcessed := atomic.NewInt32(0)
+	workerErrors := make(chan error, maxMigrationWorkers)
+	workerBarrier := sync.WaitGroup{}
+
+	for {
+		// Check for worker errors and escalate if found.
+		select {
+		case err := <-workerErrors:
+			return trace.Wrap(err)
+		default:
+		}
+
+		c := &dynamodb.ScanInput{
+			ExclusiveStartKey: startKey,
+			// Without consistent reads we may miss events as DynamoDB does not
+			// specify a sufficiently short synchronisation grace period we can
+			// rely on instead.
+			ConsistentRead: aws.Bool(true),
+			// `DynamoBatchSize*maxMigrationWorkers` is the maximum concurrent
+			// event uploads.
+			Limit:     aws.Int64(DynamoBatchSize * maxMigrationWorkers),
+			TableName: aws.String(l.Tablename),
+			// Only scan events that still have the legacy JSON string
+			// attribute and don't have the native map attribute yet.
+			// Already converted events are never returned again, which makes
+			// the migration resumable from any interruption point.
+			FilterExpression: aws.String("attribute_exists(Fields) AND attribute_not_exists(FieldsMap)"),
+		}
+
+		scanOut, err := l.svc.Scan(c)
+		if err != nil {
+			return trace.Wrap(convertError(err))
+		}
+
+		writeRequests := make([]*dynamodb.WriteRequest, 0, DynamoBatchSize*maxMigrationWorkers)
+
+		// For every item processed by this scan iteration we generate a
+		// write request.
+		for _, item := range scanOut.Items {
+			fieldsAttribute, ok := item[keyFields]
+			if !ok || fieldsAttribute.S == nil {
+				// This should not happen given the scan filter, but log and
+				// skip such records instead of aborting the whole migration.
+				l.logProblematicEvent(item, fmt.Sprintf("missing legacy %q attribute", keyFields))
+				continue
+			}
+
+			// Convert the legacy JSON string to a map.
+			var fieldsMap map[string]interface{}
+			if err := json.Unmarshal([]byte(*fieldsAttribute.S), &fieldsMap); err != nil {
+				l.logProblematicEvent(item, fmt.Sprintf("failed to unmarshal legacy %q attribute: %v", keyFields, err))
+				return trace.WrapWithMessage(err, "failed to unmarshal legacy %q attribute of an event", keyFields)
+			}
+
+			if len(fieldsMap) == 0 {
+				l.logProblematicEvent(item, fmt.Sprintf("legacy %q attribute contains no fields", keyFields))
+				return trace.CompareFailed("event has an empty %q attribute", keyFields)
+			}
+
+			// Validate that the converted map maintains the same semantic
+			// content as the original JSON representation.
+			if err := validateEventFieldsConversion(fieldsMap, *fieldsAttribute.S); err != nil {
+				l.logProblematicEvent(item, err.Error())
+				return trace.Wrap(err)
+			}
+
+			mappedFields, err := dynamodbattribute.Marshal(fieldsMap)
+			if err != nil {
+				l.logProblematicEvent(item, fmt.Sprintf("failed to marshal the converted fields: %v", err))
+				return trace.Wrap(err)
+			}
+
+			item[keyFieldsMap] = mappedFields
+
+			wr := &dynamodb.WriteRequest{
+				PutRequest: &dynamodb.PutRequest{
+					Item: item,
+				},
+			}
+
+			writeRequests = append(writeRequests, wr)
+		}
+
+		for len(writeRequests) > 0 {
+			var top int
+			if len(writeRequests) > DynamoBatchSize {
+				top = DynamoBatchSize
+			} else {
+				top = len(writeRequests)
+			}
+
+			// We need to make a copy of the slice here so it doesn't get
+			// changed later due to subslicing.
+			batch := append(make([]*dynamodb.WriteRequest, 0, DynamoBatchSize), writeRequests[:top]...)
+			writeRequests = writeRequests[top:]
+
+			// Don't exceed maximum workers.
+			for workerCounter.Load() >= maxMigrationWorkers {
+				select {
+				case <-time.After(time.Millisecond * 50):
+				case <-ctx.Done():
+					return trace.Wrap(ctx.Err())
+				}
+			}
+
+			workerCounter.Add(1)
+			workerBarrier.Add(1)
+			go func() {
+				defer workerCounter.Sub(1)
+				defer workerBarrier.Done()
+				amountProcessed := len(batch)
+
+				if err := l.uploadBatch(batch); err != nil {
+					workerErrors <- trace.Wrap(err)
+					return
+				}
+
+				total := totalProcessed.Add(int32(amountProcessed))
+				log.Infof("Migrated %d total events to the fields map format...", total)
+			}()
+		}
+
+		// Setting the startKey to the last evaluated key of the previous
+		// scan so that the next scan doesn't return processed events.
+		startKey = scanOut.LastEvaluatedKey
+
+		// If the `LastEvaluatedKey` field is not set we have finished
+		// scanning the entire dataset and we can now break out of the loop.
+		if scanOut.LastEvaluatedKey == nil {
+			break
+		}
+	}
+
+	// Wait until all upload tasks finish.
+	workerBarrier.Wait()
+
+	// Check for worker errors and escalate if found.
+	select {
+	case err := <-workerErrors:
+		return trace.Wrap(err)
+	default:
+	}
+
+	log.Info("Event fields map migration finished")
+	return nil
+}
+
+// logProblematicEvent logs the identity of an event that caused a problem
+// during the event fields map migration so that it can be identified and
+// inspected manually.
+func (l *Log) logProblematicEvent(item map[string]*dynamodb.AttributeValue, message string) {
+	var sessionID string
+	var eventIndex string
+	if value, ok := item[keySessionID]; ok && value.S != nil {
+		sessionID = *value.S
+	}
+	if value, ok := item[keyEventIndex]; ok && value.N != nil {
+		eventIndex = *value.N
+	}
+
+	l.WithFields(log.Fields{
+		"session_id":  sessionID,
+		"event_index": eventIndex,
+	}).Errorf("Problematic event during the fields map migration: %s", message)
+}
+
+// validateEventFieldsConversion checks that the given fields map maintains
+// the same semantic content as the original JSON representation.
+func validateEventFieldsConversion(fieldsMap map[string]interface{}, originalJSON string) error {
+	encoded, err := json.Marshal(fieldsMap)
+	if err != nil {
+		return trace.WrapWithMessage(err, "failed to re-encode the converted event fields")
+	}
+
+	var originalMap map[string]interface{}
+	if err := json.Unmarshal([]byte(originalJSON), &originalMap); err != nil {
+		return trace.WrapWithMessage(err, "failed to decode the original event fields JSON")
+	}
+
+	var reDecoded map[string]interface{}
+	if err := json.Unmarshal(encoded, &reDecoded); err != nil {
+		return trace.WrapWithMessage(err, "failed to decode the re-encoded event fields")
+	}
+
+	if !reflect.DeepEqual(originalMap, reDecoded) {
+		return trace.CompareFailed("converted event fields do not match the original JSON representation")
+	}
+
+	return nil
+}
+
+// fields returns the event's fields, preferring the native DynamoDB map
+// representation (FieldsMap) and falling back to the legacy JSON-encoded
+// string (Fields) for events that haven't been migrated yet.
+func (e *event) fields() (events.EventFields, error) {
+	if len(e.FieldsMap) != 0 {
+		return events.EventFields(e.FieldsMap), nil
+	}
+
+	var fields events.EventFields
+	if err := json.Unmarshal([]byte(e.Fields), &fields); err != nil {
+		return nil, trace.WrapWithMessage(err, "failed to unmarshal the event fields from the legacy %q attribute", keyFields)
+	}
+	return fields, nil
+}
