+// If the limit is reached, returns the error ErrLimitReached.
+func ReadAtMost(r io.Reader, limit int64) ([]byte, error) {
+	if limit < 0 {
+		return nil, trace.BadParameter("limit must be non-negative, got %d", limit)
+	}
+	// Read one extra byte to determine whether the limit has been reached.
+	data, err := ioutil.ReadAll(io.LimitReader(r, limit+1))
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	if int64(len(data)) > limit {
+		return data[:limit], ErrLimitReached
+	}
+	return data, nil
+}
