+// MakeTableWithTruncatedColumn creates a new instance of the table with the
+// given column names. The table adapts to the width of the terminal: the
+// column named truncatedColumn is allocated the remaining space after the
+// other columns are allocated their maximum widths, which are calculated
+// proportionally to the terminal size. Cells in the truncated column that
+// are longer than the space allocated to them are truncated with an
+// ellipsis.
+//
+// The width of the table is based on the size of the terminal; when the
+// terminal size cannot be determined, a default width of 80 columns is
+// assumed.
+//
+// If truncatedColumn does not match any of the column names, the table is
+// rendered as a regular table: every column is preserved and each column
+// is capped at its proportional maximum width.
+func MakeTableWithTruncatedColumn(columnOrder []string, rows [][]string, truncatedColumn string) Table {
+	const (
+		// truncatedColMinSize is the minimum space to reserve for the
+		// truncated column when calculating the other columns' widths.
+		truncatedColMinSize = 16
+		// defaultWidth is the terminal width to assume when the terminal
+		// size cannot be determined.
+		defaultWidth = 80
+	)
+
+	width, _, err := term.GetSize(int(os.Stdin.Fd()))
+	if err != nil || width <= 0 {
+		width = defaultWidth
+	}
+
+	// Without at least two columns there is no space to allocate to a
+	// truncated column, so fall back to a regular table.
+	if len(columnOrder) < 2 {
+		t := MakeTable(columnOrder)
+		for _, row := range rows {
+			t.AddRow(row)
+		}
+		return t
+	}
+
+	// The maximum width of the non-truncated columns is calculated
+	// proportionally to the terminal size so that the truncated column
+	// is left with at least truncatedColMinSize columns.
+	maxColWidth := (width - truncatedColMinSize) / (len(columnOrder) - 1)
+
+	t := MakeTable([]string{})
+	totalLen := 0
+	columns := make([]Column, 0, len(columnOrder))
+
+	for collIndex, colName := range columnOrder {
+		column := Column{
+			Title:         colName,
+			MaxCellLength: len(colName),
+		}
+		if colName == truncatedColumn { // truncated column is handled separately in next loop
+			columns = append(columns, column)
+			continue
+		}
+		for _, row := range rows {
+			if collIndex >= len(row) {
+				continue
+			}
+			if len(row[collIndex]) > column.MaxCellLength {
+				column.MaxCellLength = len(row[collIndex])
+			}
+		}
+		if column.MaxCellLength > maxColWidth {
+			column.MaxCellLength = maxColWidth
+			totalLen += column.MaxCellLength + 4 // "...<space>"
+		} else {
+			totalLen += column.MaxCellLength + 1 // +1 for column separator
+		}
+		columns = append(columns, column)
+	}
+
+	for _, column := range columns {
+		if column.Title == truncatedColumn {
+			// The truncated column occupies all the space left by the
+			// other columns.
+			column.MaxCellLength = width - totalLen - len("... ")
+			if column.MaxCellLength < 0 {
+				column.MaxCellLength = 0
+			}
+		}
+		t.AddColumn(column)
+	}
+
+	for _, row := range rows {
+		t.AddRow(row)
+	}
+	return t
+}
