+// ReadTeleportProxy consumes the Teleport-Proxy prefix from the reader:
+// the proxy hello signature, which must have been detected by
+// detectProto already, a JSON handshake payload and a null byte
+// terminator.
+//
+// If the handshake payload contains a valid client address, it is
+// returned, otherwise nil is returned.
+func ReadTeleportProxy(r *bufio.Reader) (net.Addr, error) {
+	// the hello signature has been peeked by detectProto, consume it
+	if _, err := r.Discard(len(sshutils.ProxyHelloSignature)); err != nil {
+		return nil, trace.Wrap(err)
+	}
