+			Size:     m.Histogram.GetSampleSum(),
+			Counter:  Counter{Count: count},
+		}
+		if prev != nil {
+			if prevEvent, ok := prev.Watcher.TopEvents[resource]; ok {
+				event.SetFreq(prevEvent.Counter, period)
+			}
+		}
+		out.TopEvents[resource] = event
+		totalCount += count
+		totalSize += event.Size
+		out.EventSize.Count += count
+		out.EventSize.Sum += event.Size
+		mergeHistogramBuckets(&out.EventSize, m.Histogram)
+	}
+
+	// calculate and store per-second rates in the
+	// sliding window circular buffers
+	if prev != nil && period > 0 {
+		if delta := float64(totalCount - prevTotalCount); delta >= 0 {
+			out.EventsPerSecond.Add(delta / float64(period/time.Second))
+		}
+		if delta := totalSize - prevTotalSize; delta >= 0 {
+			out.BytesPerSecond.Add(delta / float64(period/time.Second))
+		}
+	}
+	return out
+}
+
+// getFilteredMetrics returns a list of metrics matching the filter
+func getFilteredMetrics(metric *dto.MetricFamily, filter func(labels []*dto.LabelPair) bool) []*dto.Metric {
+	if metric == nil {
+		return nil
+	}
+	var out []*dto.Metric
+	for _, m := range metric.Metric {
+		if filter == nil || filter(m.Label) {
+			out = append(out, m)
+		}
+	}
+	return out
+}
+
+// getLabelValue returns a value of a label with a given name
+func getLabelValue(labels []*dto.LabelPair, name string) string {
+	for _, label := range labels {
+		if label.GetName() == name {
+			return label.GetValue()
+		}
+	}
+	return ""
+}
+
+// mergeHistogramBuckets adds the buckets of a histogram sample
+// to the histogram, merging buckets with equal upper bounds
+func mergeHistogramBuckets(out *Histogram, hist *dto.Histogram) {
+	for _, bucket := range hist.Bucket {
+		added := false
+		for i := range out.Buckets {
+			if out.Buckets[i].UpperBound == bucket.GetUpperBound() {
+				out.Buckets[i].Count += int64(bucket.GetCumulativeCount())
+				added = true
+				break
+			}
+		}
+		if !added {
+			out.Buckets = append(out.Buckets, Bucket{
+				Count:      int64(bucket.GetCumulativeCount()),
+				UpperBound: bucket.GetUpperBound(),
+			})
+		}
+	}
+}

