+	. "github.com/onsi/gomega"
+)
+
+var _ = Describe("Public access to getOpenSubsonicExtensions", func() {
+	var (
+		api *Router
+		ds  model.DataStore
+	)
+
+	BeforeEach(func() {
+		ds = &tests.MockDataStore{}
+		_ = ds.User(context.Background()).Put(&model.User{
+			UserName:    "admin",
+			NewPassword: "wordpass",
+		})
+		api = New(ds, nil, nil, nil, &mockPlayers{}, nil, nil, nil, nil, nil, nil, nil)
+	})
+
+	serve := func(target string) *httptest.ResponseRecorder {
+		req := httptest.NewRequest("GET", target, nil)
+		req = req.WithContext(log.NewContext(req.Context()))
+		w := httptest.NewRecorder()
+		api.ServeHTTP(w, req)
+		return w
+	}
+
+	When("requesting without credentials", func() {
+		It("returns the supported extensions as JSON when f=json", func() {
+			w := serve("/getOpenSubsonicExtensions?f=json")
+			Expect(w.Code).To(Equal(http.StatusOK))
+			Expect(w.Header().Get("Content-Type")).To(Equal("application/json"))
+
+			var wrapper responses.JsonWrapper
+			Expect(json.Unmarshal(w.Body.Bytes(), &wrapper)).To(Succeed())
+			Expect(wrapper.Subsonic.Status).To(Equal(responses.StatusOK))
+			Expect(wrapper.Subsonic.OpenSubsonicExtensions).NotTo(BeNil())
+			exts := *wrapper.Subsonic.OpenSubsonicExtensions
+			Expect(exts).To(HaveLen(3))
+			names := make([]string, 0, len(exts))
+			for _, ext := range exts {
+				names = append(names, ext.Name)
+			}
+			Expect(names).To(ConsistOf("transcodeOffset", "formPost", "songLyrics"))
+		})
+
+		It("returns the supported extensions as XML by default", func() {
+			w := serve("/getOpenSubsonicExtensions")
+			Expect(w.Code).To(Equal(http.StatusOK))
+			Expect(w.Header().Get("Content-Type")).To(Equal("application/xml"))
+			for _, name := range []string{"transcodeOffset", "formPost", "songLyrics"} {
+				Expect(w.Body.String()).To(ContainSubstring(name))
+			}
+		})
+
+		It("returns the supported extensions on the .view endpoint", func() {
+			w := serve("/getOpenSubsonicExtensions.view?f=json")
+			Expect(w.Code).To(Equal(http.StatusOK))
+			Expect(w.Header().Get("Content-Type")).To(Equal("application/json"))
+			Expect(w.Body.String()).To(ContainSubstring(`"openSubsonicExtensions"`))
+		})
+
+		It("succeeds even when invalid credentials are provided", func() {
+			w := serve("/getOpenSubsonicExtensions?f=json&u=admin&p=wrongpass&v=1.16&c=test")
+			Expect(w.Code).To(Equal(http.StatusOK))
+			var wrapper responses.JsonWrapper
+			Expect(json.Unmarshal(w.Body.Bytes(), &wrapper)).To(Succeed())
+			Expect(wrapper.Subsonic.Status).To(Equal(responses.StatusOK))
+		})
+	})
+
+	When("requesting with valid credentials", func() {
+		It("still returns the supported extensions", func() {
+			w := serve("/getOpenSubsonicExtensions?f=json&u=admin&p=wordpass&v=1.16&c=test")
+			Expect(w.Code).To(Equal(http.StatusOK))
+			var wrapper responses.JsonWrapper
+			Expect(json.Unmarshal(w.Body.Bytes(), &wrapper)).To(Succeed())
+			Expect(wrapper.Subsonic.Status).To(Equal(responses.StatusOK))
+			Expect(wrapper.Subsonic.OpenSubsonicExtensions).NotTo(BeNil())
+			Expect(*wrapper.Subsonic.OpenSubsonicExtensions).To(HaveLen(3))
+		})
+	})
+
+	When("requesting a protected endpoint without valid credentials", func() {
+		It("still requires authentication", func() {
+			w := serve("/ping?f=json&u=admin&p=wrongpass&v=1.16&c=test")
+			var wrapper responses.JsonWrapper
+			Expect(json.Unmarshal(w.Body.Bytes(), &wrapper)).To(Succeed())
+			Expect(wrapper.Subsonic.Status).To(Equal(responses.StatusFailed))
+			Expect(wrapper.Subsonic.Error.Code).To(Equal(int32(40)))
+		})
+	})
+
+	When("requesting a protected endpoint with valid credentials", func() {
+		It("works as before", func() {
+			w := serve("/ping?f=json&u=admin&p=wordpass&v=1.16&c=test")
+			var wrapper responses.JsonWrapper
+			Expect(json.Unmarshal(w.Body.Bytes(), &wrapper)).To(Succeed())
+			Expect(wrapper.Subsonic.Status).To(Equal(responses.StatusOK))
+		})
+	})
+})
+
+// The specs below verify the endpoint through a chi router mounted at /rest
+// (as Server.MountRouter does in production), over a real HTTP listener.
+var _ = Describe("getOpenSubsonicExtensions mounted at /rest", func() {
+	var (
+		ds model.DataStore
+		ts *httptest.Server
+	)
+
+	BeforeEach(func() {
+		ds = &tests.MockDataStore{}
+		_ = ds.User(context.Background()).Put(&model.User{
+			UserName:    "admin",
+			NewPassword: "wordpass",
+		})
+		api := New(ds, nil, nil, nil, &mockPlayers{}, nil, nil, nil, nil, nil, nil, nil)
+		r := chi.NewRouter()
+		r.Mount("/rest", api)
+		ts = httptest.NewServer(r)
+	})
+
+	AfterEach(func() {
+		ts.Close()
+	})
+
+	get := func(path string) (*http.Response, []byte) {
+		resp, err := http.Get(ts.URL + path)
+		if err != nil {
+			panic(err)
+		}
+		defer resp.Body.Close()
+		body, err := io.ReadAll(resp.Body)
+		if err != nil {
+			panic(err)
+		}
+		return resp, body
+	}
+
+	When("requesting the public endpoint without credentials", func() {
+		It("returns JSON with the three supported extensions", func() {
+			resp, body := get("/rest/getOpenSubsonicExtensions?f=json")
+			Expect(resp.StatusCode).To(Equal(http.StatusOK))
+			var wrapper responses.JsonWrapper
+			Expect(json.Unmarshal(body, &wrapper)).To(Succeed())
+			Expect(wrapper.Subsonic.Status).To(Equal(responses.StatusOK))
+			exts := *wrapper.Subsonic.OpenSubsonicExtensions
+			Expect(len(exts)).To(Equal(3))
+			names := []string{}
+			for _, e := range exts {
+				names = append(names, fmt.Sprintf("%s-%d", e.Name, e.Versions[0]))
+			}
+			Expect(names).To(ConsistOf("transcodeOffset-1", "formPost-1", "songLyrics-1"))
+		})
+
+		It("returns XML when no format is requested", func() {
+			resp, body := get("/rest/getOpenSubsonicExtensions")
+			Expect(resp.StatusCode).To(Equal(http.StatusOK))
+			Expect(resp.Header.Get("Content-Type")).To(Equal("application/xml"))
+			Expect(string(body)).To(ContainSubstring("openSubsonicExtensions"))
+		})
+	})
+
+	When("requesting a protected endpoint without credentials", func() {
+		It("rejects the request", func() {
+			resp, body := get("/rest/ping?f=json&u=admin&p=wrongpass&v=1.16&c=test")
+			Expect(resp.StatusCode).To(Equal(http.StatusOK))
+			var wrapper responses.JsonWrapper
+			Expect(json.Unmarshal(body, &wrapper)).To(Succeed())
+			Expect(wrapper.Subsonic.Status).To(Equal(responses.StatusFailed))
+			Expect(wrapper.Subsonic.Error.Code).To(Equal(int32(40)))
+		})
+	})
+})

