--- /dev/null
+++ b/model/criteria/fields.go
@@ -0,0 +1,47 @@
+package criteria
+
+import (
+	"encoding/json"
+	"time"
+)
+
+// fieldMap maps the criteria field names to the corresponding (fully qualified) SQL column names
+var fieldMap = map[string]string{
+	"title":   "media_file.title",
+	"artist":  "media_file.artist",
+	"album":   "media_file.album",
+	"loved":   "annotation.starred",
+	"year":    "media_file.year",
+	"comment": "media_file.comment",
+}
+
+// sqlField translates a criteria field name to the corresponding SQL column name.
+// If the field is not in the fieldMap, it is returned unchanged
+func sqlField(field string) string {
+	if mapped, ok := fieldMap[field]; ok {
+		return mapped
+	}
+	return field
+}
+
+// Time is a wrapper around time.Time, that serializes to JSON as a "YYYY-MM-DD" (ISO 8601) date string
+type Time time.Time
+
+// MarshalJSON serializes the Time as a "YYYY-MM-DD" string
+func (t Time) MarshalJSON() ([]byte, error) {
+	return json.Marshal(time.Time(t).Format("2006-01-02"))
+}
+
+// UnmarshalJSON deserializes a "YYYY-MM-DD" string to a Time
+func (t *Time) UnmarshalJSON(data []byte) error {
+	var s string
+	if err := json.Unmarshal(data, &s); err != nil {
+		return err
+	}
+	parsed, err := time.ParseInLocation("2006-01-02", s, time.Local)
+	if err != nil {
+		return err
+	}
+	*t = Time(parsed)
+	return nil
+}
diff --git a/model/criteria/json.go b/model/criteria/json.go
new file mode 100644
index 00000000..224876af
--- /dev/null
+++ b/model/criteria/json.go
@@ -0,0 +1,254 @@
+package criteria
+
+import (
+	"encoding/json"
+	"fmt"
+
+	"github.com/Masterminds/squirrel"
+)
+
+// MarshalJSON serializes an All expression to a JSON object with an "all" key
+func (a All) MarshalJSON() ([]byte, error) {
+	return json.Marshal(struct {
+		All []squirrel.Sqlizer `json:"all"`
+	}{All: a})
+}
+
+// MarshalJSON serializes an Any expression to a JSON object with an "any" key
+func (a Any) MarshalJSON() ([]byte, error) {
+	return json.Marshal(struct {
+		Any []squirrel.Sqlizer `json:"any"`
+	}{Any: a})
+}
+
+func (i Is) MarshalJSON() ([]byte, error)       { return marshalOp("is", i.FieldName, i.Value) }
+func (i IsNot) MarshalJSON() ([]byte, error)    { return marshalOp("isNot", i.FieldName, i.Value) }
+func (g Gt) MarshalJSON() ([]byte, error)       { return marshalOp("gt", g.FieldName, g.Value) }
+func (l Lt) MarshalJSON() ([]byte, error)       { return marshalOp("lt", l.FieldName, l.Value) }
+func (b Before) MarshalJSON() ([]byte, error)   { return marshalOp("before", b.FieldName, b.Value) }
+func (a After) MarshalJSON() ([]byte, error)    { return marshalOp("after", a.FieldName, a.Value) }
+func (c Contains) MarshalJSON() ([]byte, error) { return marshalOp("contains", c.FieldName, c.Value) }
+func (c NotContains) MarshalJSON() ([]byte, error) {
+	return marshalOp("notContains", c.FieldName, c.Value)
+}
+func (c StartsWith) MarshalJSON() ([]byte, error) {
+	return marshalOp("startsWith", c.FieldName, c.Value)
+}
+func (c EndsWith) MarshalJSON() ([]byte, error) { return marshalOp("endsWith", c.FieldName, c.Value) }
+func (r InTheRange) MarshalJSON() ([]byte, error) {
+	return marshalOp("inTheRange", r.FieldName, r.Value)
+}
+func (i InTheLast) MarshalJSON() ([]byte, error) { return marshalOp("inTheLast", i.FieldName, i.Value) }
+func (i NotInTheLast) MarshalJSON() ([]byte, error) {
+	return marshalOp("notInTheLast", i.FieldName, i.Value)
+}
+
+// marshalOp serializes an operator to a JSON object with a single key (the operator name),
+// holding a "field"/"value" object
+func marshalOp(key, field string, value interface{}) ([]byte, error) {
+	return json.Marshal(map[string]map[string]interface{}{
+		key: {"field": field, "value": value},
+	})
+}
+
+// MarshalJSON serializes the criteria to a JSON object, with the expression ("all" or "any" key)
+// merged with the "sort", "order", "max" and "offset" pagination fields
+func (c Criteria) MarshalJSON() ([]byte, error) {
+	result := map[string]interface{}{
+		"sort":   c.Sort,
+		"order":  c.Order,
+		"max":    c.Max,
+		"offset": c.Offset,
+	}
+	if c.Expression != nil {
+		expr, err := json.Marshal(c.Expression)
+		if err != nil {
+			return nil, err
+		}
+		var m map[string]interface{}
+		if err := json.Unmarshal(expr, &m); err != nil {
+			return nil, err
+		}
+		for k, v := range m {
+			result[k] = v
+		}
+	}
+	return json.Marshal(result)
+}
+
+// UnmarshalJSON deserializes the criteria from a JSON object, reconstructing the expression
+// from the "all", "any" or operator keys, and the "sort", "order", "max" and "offset" fields
+func (c *Criteria) UnmarshalJSON(data []byte) error {
+	var raw map[string]json.RawMessage
+	if err := json.Unmarshal(data, &raw); err != nil {
+		return err
+	}
+	var err error
+	for key, rawValue := range raw {
+		switch key {
+		case "sort":
+			err = json.Unmarshal(rawValue, &c.Sort)
+		case "order":
+			err = json.Unmarshal(rawValue, &c.Order)
+		case "max":
+			err = json.Unmarshal(rawValue, &c.Max)
+		case "offset":
+			err = json.Unmarshal(rawValue, &c.Offset)
+		case "all":
+			var items []squirrel.Sqlizer
+			if err = unmarshalConjItems(rawValue, &items); err == nil {
+				c.Expression = All(items)
+			}
+		case "any":
+			var items []squirrel.Sqlizer
+			if err = unmarshalConjItems(rawValue, &items); err == nil {
+				c.Expression = Any(items)
+			}
+		default:
+			// a single operator at the top level
+			if c.Expression == nil {
+				var sq squirrel.Sqlizer
+				sq, err = unmarshalOperator(key, rawValue)
+				if err == nil {
+					c.Expression = sq
+				}
+			}
+		}
+		if err != nil {
+			return err
+		}
+	}
+	return nil
+}
+
+// unmarshalConjItems deserializes a JSON array of expressions
+func unmarshalConjItems(data json.RawMessage, out *[]squirrel.Sqlizer) error {
+	var items []json.RawMessage
+	if err := json.Unmarshal(data, &items); err != nil {
+		return err
+	}
+	result := make([]squirrel.Sqlizer, 0, len(items))
+	for _, item := range items {
+		sq, err := unmarshalSqlizer(item)
+		if err != nil {
+			return err
+		}
+		result = append(result, sq)
+	}
+	*out = result
+	return nil
+}
+
+// unmarshalSqlizer deserializes a JSON object representing an expression (an operator,
+// or a nested "all"/"any" group)
+func unmarshalSqlizer(data []byte) (squirrel.Sqlizer, error) {
+	var raw map[string]json.RawMessage
+	if err := json.Unmarshal(data, &raw); err != nil {
+		return nil, err
+	}
+	for key, rawValue := range raw {
+		switch key {
+		case "all":
+			var items []squirrel.Sqlizer
+			if err := unmarshalConjItems(rawValue, &items); err != nil {
+				return nil, err
+			}
+			return All(items), nil
+		case "any":
+			var items []squirrel.Sqlizer
+			if err := unmarshalConjItems(rawValue, &items); err != nil {
+				return nil, err
+			}
+			return Any(items), nil
+		default:
+			return unmarshalOperator(key, rawValue)
+		}
+	}
+	return nil, fmt.Errorf("invalid criteria expression: %s", string(data))
+}
+
+// unmarshalOperator deserializes a JSON object representing a single operator
+func unmarshalOperator(key string, rawValue json.RawMessage) (squirrel.Sqlizer, error) {
+	switch key {
+	case "is":
+		var op Is
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "isNot":
+		var op IsNot
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "gt":
+		var op Gt
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "lt":
+		var op Lt
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "before":
+		var op Before
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "after":
+		var op After
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "contains":
+		var op Contains
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "notContains":
+		var op NotContains
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "startsWith":
+		var op StartsWith
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "endsWith":
+		var op EndsWith
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "inTheRange":
+		var op InTheRange
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "inTheLast":
+		var op InTheLast
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	case "notInTheLast":
+		var op NotInTheLast
+		if err := json.Unmarshal(rawValue, &op); err != nil {
+			return nil, err
+		}
+		return op, nil
+	default:
+		return nil, fmt.Errorf("unknown operator '%s'", key)
+	}
+}
diff --git a/model/criteria/operators.go b/model/criteria/operators.go
new file mode 100644
index 00000000..8afef003
--- /dev/null
+++ b/model/criteria/operators.go
@@ -0,0 +1,231 @@
+package criteria
+
+import (
+	"fmt"
+	"strconv"
+	"time"
+
+	"github.com/Masterminds/squirrel"
+)
+
+// All is a logical conjunction (AND) of the given conditions
+type All squirrel.And
+
+// Any is a logical disjunction (OR) of the given conditions
+type Any squirrel.Or
+
+// ToSql generates a SQL expression with all conditions joined by AND, grouped in parentheses
+func (a All) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.And(a).ToSql()
+}
+
+// ToSql generates a SQL expression with all conditions joined by OR, grouped in parentheses
+func (a Any) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Or(a).ToSql()
+}
+
+// Is checks if a field is equal to a value
+type Is struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL equality condition for the field
+func (i Is) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Eq{sqlField(i.FieldName): i.Value}.ToSql()
+}
+
+// IsNot checks if a field is not equal to a value
+type IsNot struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL inequality condition for the field
+func (i IsNot) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.NotEq{sqlField(i.FieldName): i.Value}.ToSql()
+}
+
+// Gt checks if a field is greater than a value
+type Gt struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL "greater than" condition for the field
+func (g Gt) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Gt{sqlField(g.FieldName): g.Value}.ToSql()
+}
+
+// Lt checks if a field is less than a value
+type Lt struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL "less than" condition for the field
+func (l Lt) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Lt{sqlField(l.FieldName): l.Value}.ToSql()
+}
+
+// Before checks if a date field is before a date
+type Before struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL "less than" date condition for the field
+func (b Before) ToSql() (sql string, args []interface{}, err error) {
+	date, err := parseDate(b.Value)
+	if err != nil {
+		return "", nil, err
+	}
+	return squirrel.Lt{sqlField(b.FieldName): date}.ToSql()
+}
+
+// After checks if a date field is after a date
+type After struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL "greater than" date condition for the field
+func (a After) ToSql() (sql string, args []interface{}, err error) {
+	date, err := parseDate(a.Value)
+	if err != nil {
+		return "", nil, err
+	}
+	return squirrel.Gt{sqlField(a.FieldName): date}.ToSql()
+}
+
+// Contains checks if a text field contains a value
+type Contains struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL ILIKE condition, with the value wrapped in %
+func (c Contains) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.ILike{sqlField(c.FieldName): fmt.Sprintf("%%%v%%", c.Value)}.ToSql()
+}
+
+// NotContains checks if a text field does not contain a value
+type NotContains struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL NOT ILIKE condition, with the value wrapped in %
+func (c NotContains) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.NotILike{sqlField(c.FieldName): fmt.Sprintf("%%%v%%", c.Value)}.ToSql()
+}
+
+// StartsWith checks if a text field starts with a value
+type StartsWith struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL ILIKE condition, with a trailing % on the value
+func (c StartsWith) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.ILike{sqlField(c.FieldName): fmt.Sprintf("%v%%", c.Value)}.ToSql()
+}
+
+// EndsWith checks if a text field ends with a value
+type EndsWith struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL ILIKE condition, with a leading % on the value
+func (c EndsWith) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.ILike{sqlField(c.FieldName): fmt.Sprintf("%%%v", c.Value)}.ToSql()
+}
+
+// InTheRange checks if a numeric or date field is between two values (>= min AND <= max)
+type InTheRange struct {
+	FieldName string        `json:"field"`
+	Value     []interface{} `json:"value"`
+}
+
+// ToSql generates an SQL range condition with >= and <= for the field
+func (r InTheRange) ToSql() (sql string, args []interface{}, err error) {
+	if len(r.Value) != 2 {
+		return "", nil, fmt.Errorf("invalid range for 'inTheRange' operator: expected 2 values, got %d", len(r.Value))
+	}
+	return squirrel.And{
+		squirrel.GtOrEq{sqlField(r.FieldName): r.Value[0]},
+		squirrel.LtOrEq{sqlField(r.FieldName): r.Value[1]},
+	}.ToSql()
+}
+
+// InTheLast checks if a date field is within the last N days
+type InTheLast struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL "greater than" condition with the date N days ago
+func (i InTheLast) ToSql() (sql string, args []interface{}, err error) {
+	days, err := parseDays(i.Value)
+	if err != nil {
+		return "", nil, err
+	}
+	date := time.Now().Add(time.Duration(-days) * 24 * time.Hour)
+	return squirrel.Gt{sqlField(i.FieldName): date}.ToSql()
+}
+
+// NotInTheLast checks if a date field is NOT within the last N days (or is null)
+type NotInTheLast struct {
+	FieldName string      `json:"field"`
+	Value     interface{} `json:"value"`
+}
+
+// ToSql generates an SQL condition with OR of "less than" the date N days ago or IS NULL
+func (i NotInTheLast) ToSql() (sql string, args []interface{}, err error) {
+	days, err := parseDays(i.Value)
+	if err != nil {
+		return "", nil, err
+	}
+	date := time.Now().Add(time.Duration(-days) * 24 * time.Hour)
+	return squirrel.Or{
+		squirrel.Lt{sqlField(i.FieldName): date},
+		squirrel.Eq{sqlField(i.FieldName): nil},
+	}.ToSql()
+}
+
+func parseDate(v interface{}) (time.Time, error) {
+	switch d := v.(type) {
+	case time.Time:
+		return d, nil
+	case Time:
+		return time.Time(d), nil
+	case string:
+		if parsed, err := time.ParseInLocation("2006-01-02", d, time.Local); err == nil {
+			return parsed, nil
+		}
+		if parsed, err := time.Parse(time.RFC3339, d); err == nil {
+			return parsed, nil
+		}
+		return time.Time{}, fmt.Errorf("invalid date: %s", d)
+	default:
+		return time.Time{}, fmt.Errorf("invalid date value: %v", v)
+	}
+}
+
+func parseDays(v interface{}) (int, error) {
+	switch n := v.(type) {
+	case int:
+		return n, nil
+	case int32:
+		return int(n), nil
+	case int64:
+		return int(n), nil
+	case float64:
+		return int(n), nil
+	case string:
+		return strconv.Atoi(n)
+	default:
+		return 0, fmt.Errorf("invalid value for 'inTheLast' operator: %v", v)
+	}
+}

