diff --git a/db/backup.go b/db/backup.go
new file mode 100644
index 00000000..cb20fb23
--- /dev/null
+++ b/db/backup.go
@@ -0,0 +1,251 @@
+package db
+
+import (
+	"context"
+	"database/sql"
+	"fmt"
+	"io"
+	"os"
+	"path/filepath"
+	"sort"
+	"strings"
+	"time"
+
+	"github.com/mattn/go-sqlite3"
+	"github.com/navidrome/navidrome/conf"
+	"github.com/navidrome/navidrome/log"
+)
+
+const (
+	// backupFilePrefix is the prefix of all backup file names
+	backupFilePrefix = "navidrome_backup_"
+	// backupFileSuffix is the suffix of all backup file names
+	backupFileSuffix = ".db"
+	// backupTimeFormat is the format of the timestamp embedded in backup file names.
+	// It is chosen so that file names are sorted chronologically in lexicographic order.
+	backupTimeFormat = "2006-01-02T15-04-05.000"
+)
+
+// backupFileName returns the file name of a backup created at time t
+func backupFileName(t time.Time) string {
+	return backupFilePrefix + t.Format(backupTimeFormat) + backupFileSuffix
+}
+
+// backupFilePath returns the full path of a backup created at time t, inside the
+// directory configured in conf.Server.Backup.Path
+func backupFilePath(t time.Time) string {
+	return filepath.Join(conf.Server.Backup.Path, backupFileName(t))
+}
+
+// Backup creates an online backup of the current database at the directory configured in
+// conf.Server.Backup.Path, and returns the path of the created backup file.
+func (d *db) Backup(ctx context.Context) (string, error) {
+	backupDir := conf.Server.Backup.Path
+	if backupDir == "" {
+		return "", fmt.Errorf("backup path is not configured")
+	}
+	if err := os.MkdirAll(backupDir, 0o755); err != nil {
+		return "", fmt.Errorf("error creating backup directory %s: %w", backupDir, err)
+	}
+	destPath := backupFilePath(time.Now())
+
+	// Open the destination backup file
+	destDB, err := sql.Open(Driver, destPath)
+	if err != nil {
+		return "", fmt.Errorf("error opening backup file %s: %w", destPath, err)
+	}
+	defer destDB.Close()
+
+	destConn, dc, err := sqliteConnOf(destDB, ctx)
+	if err != nil {
+		return "", fmt.Errorf("error connecting to backup file %s: %w", destPath, err)
+	}
+	defer destConn.Close()
+
+	srcConn, sc, err := sqliteConnOf(d.writeDB, ctx)
+	if err != nil {
+		return "", fmt.Errorf("error connecting to database: %w", err)
+	}
+	defer srcConn.Close()
+
+	if err := copyDatabase(dc, "main", sc, "main"); err != nil {
+		return "", fmt.Errorf("error creating backup %s: %w", destPath, err)
+	}
+	// Set the backup file to rollback journal mode, so it is self-contained and does not
+	// rely on (or create) WAL/SHM companion files
+	if _, err := destConn.ExecContext(ctx, "PRAGMA journal_mode=DELETE"); err != nil {
+		return "", fmt.Errorf("error finalizing backup file %s: %w", destPath, err)
+	}
+	log.Debug("Created database backup", "path", destPath)
+	return destPath, nil
+}
+
+// Restore restores the current database from the backup file at path, using the SQLite
+// online backup API. The backup file must exist and be a valid SQLite database.
+func (d *db) Restore(ctx context.Context, path string) error {
+	if err := checkBackupFile(path); err != nil {
+		return err
+	}
+	// Open the backup file as the source, read-only, so we never modify it
+	srcDB, err := sql.Open(Driver, "file:"+path+"?mode=ro")
+	if err != nil {
+		return fmt.Errorf("error opening backup file %s: %w", path, err)
+	}
+	defer srcDB.Close()
+
+	srcConn, sc, err := sqliteConnOf(srcDB, ctx)
+	if err != nil {
+		return fmt.Errorf("error connecting to backup file %s: %w", path, err)
+	}
+	defer srcConn.Close()
+
+	destConn, dc, err := sqliteConnOf(d.writeDB, ctx)
+	if err != nil {
+		return fmt.Errorf("error connecting to database: %w", err)
+	}
+	defer destConn.Close()
+
+	if err := copyDatabase(dc, "main", sc, "main"); err != nil {
+		return fmt.Errorf("error restoring database from %s: %w", path, err)
+	}
+	log.Debug("Restored database", "path", path)
+	return nil
+}
+
+// Prune removes old backup files according to the configured retention policy
+// (conf.Server.Backup.Count), and returns the number of files pruned.
+func (d *db) Prune(ctx context.Context) (int, error) {
+	return prune(ctx)
+}
+
+// prune deletes old backup files from the directory configured in conf.Server.Backup.Path,
+// keeping only the latest conf.Server.Backup.Count ones, in descending timestamp order.
+// It returns the number of files deleted.
+func prune(ctx context.Context) (int, error) {
+	backupDir := conf.Server.Backup.Path
+	keep := conf.Server.Backup.Count
+	if backupDir == "" {
+		return 0, nil
+	}
+	entries, err := os.ReadDir(backupDir)
+	if err != nil {
+		return 0, fmt.Errorf("error reading backup directory %s: %w", backupDir, err)
+	}
+	backups := make([]backupInfo, 0, len(entries))
+	for _, e := range entries {
+		if e.IsDir() {
+			continue
+		}
+		name := e.Name()
+		if !strings.HasPrefix(name, backupFilePrefix) || !strings.HasSuffix(name, backupFileSuffix) {
+			continue
+		}
+		ts, err := time.ParseInLocation(backupTimeFormat,
+			strings.TrimSuffix(strings.TrimPrefix(name, backupFilePrefix), backupFileSuffix), time.UTC)
+		if err != nil {
+			// Unrecognized timestamp format: fall back to the file modification time
+			info, iErr := e.Info()
+			if iErr != nil {
+				continue
+			}
+			ts = info.ModTime()
+		}
+		backups = append(backups, backupInfo{path: filepath.Join(backupDir, name), ts: ts})
+	}
+	// Sort by descending timestamp (newest first)
+	sort.Slice(backups, func(i, j int) bool { return backups[i].ts.After(backups[j].ts) })
+
+	pruned := 0
+	for i, b := range backups {
+		if i < keep {
+			continue
+		}
+		if err := os.Remove(b.path); err != nil {
+			return pruned, fmt.Errorf("error deleting backup file %s: %w", b.path, err)
+		}
+		pruned++
+		// Also remove any WAL/SHM companion files, so the backup is fully deleted
+		for _, suffix := range []string{"-wal", "-shm"} {
+			if err := os.Remove(b.path + suffix); err != nil && !os.IsNotExist(err) {
+				return pruned, fmt.Errorf("error deleting backup file %s%s: %w", b.path, suffix, err)
+			}
+		}
+		log.Debug("Pruned old backup", "path", b.path)
+	}
+	return pruned, nil
+}
+
+type backupInfo struct {
+	path string
+	ts   time.Time
+}
+
+// sqliteConnOf gets a connection from the pool of d and returns it together with the
+// underlying *sqlite3.SQLiteConn, so it can be used with the SQLite backup API.
+// The caller is responsible for closing the returned *sql.Conn.
+func sqliteConnOf(d *sql.DB, ctx context.Context) (*sql.Conn, *sqlite3.SQLiteConn, error) {
+	conn, err := d.Conn(ctx)
+	if err != nil {
+		return nil, nil, err
+	}
+	var sc *sqlite3.SQLiteConn
+	err = conn.Raw(func(driverConn any) error {
+		var ok bool
+		sc, ok = driverConn.(*sqlite3.SQLiteConn)
+		if !ok {
+			return fmt.Errorf("unexpected driver connection type %T", driverConn)
+		}
+		return nil
+	})
+	if err != nil {
+		_ = conn.Close()
+		return nil, nil, err
+	}
+	return conn, sc, nil
+}
+
+// copyDatabase copies the srcSchema of srcConn to the destSchema of destConn, using the
+// SQLite online backup API. This allows the backup to be taken (or restored) while the
+// database is in use.
+func copyDatabase(destConn *sqlite3.SQLiteConn, destSchema string, srcConn *sqlite3.SQLiteConn, srcSchema string) error {
+	b, err := destConn.Backup(destSchema, srcConn, srcSchema)
+	if err != nil {
+		return err
+	}
+	for {
+		done, err := b.Step(-1)
+		if err != nil {
+			_ = b.Finish()
+			return err
+		}
+		if done {
+			break
+		}
+	}
+	return b.Finish()
+}
+
+// checkBackupFile validates that the file at path exists and has a valid SQLite header,
+// so the database is never overwritten with an invalid file.
+func checkBackupFile(path string) error {
+	info, err := os.Stat(path)
+	if err != nil {
+		return fmt.Errorf("backup file not found: %w", err)
+	}
+	if info.Size() < 16 {
+		return fmt.Errorf("backup file is not a valid SQLite database (too small): %s", path)
+	}
+	f, err := os.Open(path)
+	if err != nil {
+		return fmt.Errorf("error opening backup file: %w", err)
+	}
+	defer f.Close()
+	header := make([]byte, 16)
+	if _, err := io.ReadFull(f, header); err != nil {
+		return fmt.Errorf("error reading backup file header: %w", err)
+	}
+	if string(header) != "SQLite format 3\x00" {
+		return fmt.Errorf("backup file is not a valid SQLite database: %s", path)
+	}
+	return nil
+}
