+// aggregated from the genres of their tracks
+func (r *albumRepository) getAlbumGenres(ids []string) (map[string]model.Genres, error) {
+	sel := Select("f.album_id as album_id", "g.id", "g.name").
+		From("media_file f").
+		Join("media_file_genres mfg on mfg.media_file_id = f.id").
+		Join("genre g on g.id = mfg.genre_id").
+		Where(Eq{"f.album_id": ids}).
+		GroupBy("f.album_id", "g.id", "g.name").
+		OrderBy("f.album_id", "g.name")
+	var rows []struct {
+		model.Genre
+		AlbumId string
+	}
+	if err := r.queryAll(sel, &rows); err != nil {
+		return nil, err
+	}
+	result := make(map[string]model.Genres, len(ids))
+	for _, row := range rows {
+		result[row.AlbumId] = append(result[row.AlbumId], row.Genre)
+	}
+	return result, nil
+}
