+// handleLoginFromHeaders handles a login based on the headers set by a
+// whitelisted reverse proxy (see ReverseProxyWhitelist and
+// ReverseProxyUserHeader). It returns a payload with the user's
+// authentication data, so the UI can initialize the session without the user
+// having to log in again, or nil if the request is not from a whitelisted
+// proxy, the username header is not set, or the user could not be resolved.
+func handleLoginFromHeaders(ds model.DataStore, r *http.Request) map[string]interface{} {
+	ctx := r.Context()
+	username := strings.TrimSpace(r.Header.Get(conf.Server.ReverseProxyUserHeader))
+	if username == "" {
+		return nil
+	}
+
+	if !validateIPAgainstList(r.RemoteAddr, conf.Server.ReverseProxyWhitelist) {
+		return nil
+	}
+
+	auth.Init(ds)
+
+	user, err := ds.User(ctx).FindByUsername(username)
+	if err == model.ErrNotFound {
+		// The user is created on first login. The first user created is set as
+		// admin.
+		count, _ := ds.User(ctx).CountAll()
+		user = &model.User{
+			ID:       uuid.NewString(),
+			UserName: username,
+			Name:     strings.Title(username),
+			IsAdmin:  count == 0,
+		}
+		err = ds.User(ctx).Put(user)
+		if err != nil {
+			log.Error(ctx, "Could not create user from reverse proxy header", "username", username, err)
+			return nil
+		}
+	} else if err != nil {
+		log.Error(ctx, "Could not find user", "username", username, err)
+		return nil
+	}
+
+	if err := ds.User(ctx).UpdateLastLoginAt(user.ID); err != nil {
+		log.Error(ctx, "Could not update LastLoginAt", "username", username, err)
+	}
+
+	tokenString, err := auth.CreateToken(user)
+	if err != nil {
+		log.Error(ctx, "Could not create token", "username", username, err)
+		return nil
+	}
+
+	salt := generateSubsonicSalt()
+	log.Debug(ctx, "User authenticated via reverse proxy", "username", username)
+	return map[string]interface{}{
+		"id":            user.ID,
+		"username":      user.UserName,
+		"name":          user.Name,
+		"isAdmin":       user.IsAdmin,
+		"token":         tokenString,
+		"subsonicSalt":  salt,
+		"subsonicToken": generateSubsonicToken(user.Password, salt),
+	}
+}
+
+// validateIPAgainstList checks if the given remote address is whitelisted in
+// the given list of CIDR ranges. The remote address can be in "IP:port"
+// format, or "@" if the request was received through a Unix socket. The
+// whitelist is a comma-separated list of IPv4 and/or IPv6 CIDR ranges (or
+// single IPs), which can also be in "IP:port" format. Requests coming through
+// a Unix socket can be whitelisted with the special value "@". Invalid
+// entries are ignored. If the whitelist is empty, no address is valid.
+func validateIPAgainstList(ip, whitelist string) bool {
+	if whitelist == "" {
+		return false
+	}
+
+	srcIP := extractIP(ip)
+	for _, entry := range strings.Split(whitelist, ",") {
+		entry = strings.TrimSpace(entry)
+		if entry == "" {
+			continue
+		}
+		if entry == "@" {
+			// "@" in the whitelist allows requests coming through a Unix socket
+			if ip == "@" {
+				return true
+			}
+			continue
+		}
+		if srcIP == nil {
+			continue
+		}
+		if ipNet, ok := parseCIDREntry(entry); ok && ipNet.Contains(srcIP) {
+			return true
+		}
+	}
+	return false
+}
+
+// extractIP extracts the IP from a remote address, which can be in "IP:port"
+// format. It returns nil if the address does not contain a valid IP (as is the
+// case for "@", requests coming through a Unix socket).
+func extractIP(remoteAddr string) net.IP {
+	host, _, err := net.SplitHostPort(remoteAddr)
+	if err != nil {
+		host = remoteAddr
+	}
+	return net.ParseIP(host)
+}
+
+// parseCIDREntry parses a single whitelist entry, which can be an IPv4 or
+// IPv6 CIDR range, or a single IP, optionally followed by a port. It returns
+// false if the entry is not valid.
+func parseCIDREntry(entry string) (*net.IPNet, bool) {
+	if _, ipNet, err := net.ParseCIDR(entry); err == nil {
+		return ipNet, true
+	}
+	host, _, err := net.SplitHostPort(entry)
+	if err != nil {
+		host = entry
+	}
+	if ip := net.ParseIP(host); ip != nil {
+		bits := net.IPv4len * 8
+		if ip.To4() == nil {
+			bits = net.IPv6len * 8
+		}
+		return &net.IPNet{IP: ip, Mask: net.CIDRMask(bits, bits)}, true
+	}
+	return nil, false
+}
+
+func generateSubsonicSalt() string {
+	sum := md5.Sum([]byte(uuid.NewString()))
+	return hex.EncodeToString(sum[:])[:6]
+}
+
+func generateSubsonicToken(password, salt string) string {
+	sum := md5.Sum([]byte(password + salt))
+	return hex.EncodeToString(sum[:])
+}
