+				results[i] = singleton.GetInstance(constructor)
+				atomic.AddInt32(&numCalls, 1)
+				done.Done()
+			}(i)
+			prepare.Done()
+		}
+		prepare.Wait()
+		start.Done()
+		done.Wait()
+
+		Expect(numCalls).To(Equal(int32(maxCalls)))
+		Expect(numInstances).To(Equal(int32(1)))
+		for i := 1; i < maxCalls; i++ {
+			Expect(results[i]).To(Equal(results[0]), "all concurrent calls must receive the same instance")
+		}
