+import { ReactNode } from 'react';
+
+import { Tooltip } from '@proton/components';
+import clsx from '@proton/utils/clsx';
+
+interface Props {
+    text: string;
+    tooltipText: ReactNode;
+    selected?: boolean;
+}
+
+/**
+ * Generic Proton badge, to be displayed next to a sender or recipient.
+ * The badge text and the tooltip are customizable, and the badge can be styled
+ * differently when the related item is selected.
+ */
+const ProtonBadge = ({ text, tooltipText, selected = false }: Props) => {
+    return (
+        <Tooltip title={tooltipText}>
+            <span
+                className={clsx([
+                    'proton-badge ml0-25 flex-item-noshrink',
+                    selected ? 'proton-badge--selected' : 'proton-badge--not-selected',
+                ])}
+                data-testid="proton-badge"
+            >
+                {text}
+            </span>
+        </Tooltip>
+    );
+};
+
+export default ProtonBadge;
