+/**
+ * Check if a recipient or the first recipient of a group is using a Proton domain
+ * @param recipientOrGroup the recipient or group to check
+ */
+const isProtonRecipient = (recipientOrGroup: RecipientOrGroup): boolean => {
+    const recipient = recipientOrGroup.recipient || recipientOrGroup.group?.recipients?.[0];
+    const [, domain] = getEmailParts(recipient?.Address || '');
+    return PROTONMAIL_DOMAINS.includes(domain.toLowerCase());
+};
+
+/**
+ * Check if an element is from a Proton sender
+ * @deprecated use isProtonSender instead
+ */
 export const isFromProton = (element: Element) => {
     return !!element.IsProton;
 };
+
+/**
+ * Check if an element is to be considered as coming from a verified Proton sender.
+ * For regular elements, this relies on the element IsProton flag, which is set by the
+ * backend for messages sent from a Proton Mail account.
+ * When the element displays recipients (e.g. in the sent folders), the original sender
+ * is the user themselves, so the check is done against the first displayed recipient
+ * (or group) instead.
+ *
+ * @param element the element to check
+ * @param recipientOrGroup the first recipient or group displayed for the element
+ * @param displayRecipients whether the element displays recipients instead of senders
+ */
+export const isProtonSender = (element: Element, recipientOrGroup: RecipientOrGroup, displayRecipients: boolean): boolean => {
+    if (displayRecipients) {
+        return isProtonRecipient(recipientOrGroup);
+    }
+    return !!element.IsProton;
+};
