diff --git a/applications/mail/src/app/helpers/message/referralVerify.test.ts b/applications/mail/src/app/helpers/message/referralVerify.test.ts
new file mode 100644
index 000000000..6a485b6ba
--- /dev/null
+++ b/applications/mail/src/app/helpers/message/referralVerify.test.ts
@@ -0,0 +1,218 @@
+import { Address, MailSettings, UserSettings } from '@proton/shared/lib/interfaces';
+import { getProtonMailSignature } from '@proton/shared/lib/mail/signature';
+import { eoDefaultUserSettings } from '@proton/shared/lib/mail/eo/constants';
+import { defaultFontStyle } from '@proton/components/components/editor/helpers';
+import { MESSAGE_ACTIONS } from '../../constants';
+import { MessageStateWithData } from '../../logic/messages/messagesTypes';
+import { toText } from '../parserHtml';
+import {
+    getProtonSignature,
+    templateBuilder,
+    insertSignature,
+    changeSignature,
+} from './messageSignature';
+import { createNewDraft, generateBlockquote } from './messageDraft';
+import { textToHtml } from '../textToHtml';
+
+const REFERRAL_LINK = 'https://proton.me/u/123';
+const userSettingsReferral = { Referral: { Link: REFERRAL_LINK, Eligible: true } } as UserSettings;
+const userSettingsNone = eoDefaultUserSettings;
+
+const mailSettingsPm = { PMSignature: 1, PMSignatureReferralLink: 1 } as MailSettings;
+const fontStyle = defaultFontStyle(mailSettingsPm);
+const address = {
+    ID: 'addressid',
+    DisplayName: 'name',
+    Email: 'email',
+    Status: 1,
+    Receive: 1,
+    Send: 1,
+    Signature: 'my signature',
+} as Address;
+const addresses: Address[] = [address];
+
+const count = (haystack: string, needle: string) => haystack.split(needle).length - 1;
+
+// The plain text form of the signature block (as it appears in a plain text draft body)
+const sigText = (signature: string, userSettings: Partial<UserSettings>) =>
+    toText(templateBuilder(signature, mailSettingsPm, fontStyle, false, true, userSettings)).replace(/\u200B/g, '').trim();
+
+describe('referral signature verification', () => {
+    it('getProtonSignature uses referral link when enabled', () => {
+        const withReferral = getProtonSignature(mailSettingsPm, userSettingsReferral);
+        expect(withReferral).toBe(
+            getProtonMailSignature({ isReferralProgramLinkEnabled: true, referralProgramUserLink: REFERRAL_LINK })
+        );
+        expect(withReferral).toContain(`href="${REFERRAL_LINK}"`);
+
+        const standard = getProtonSignature(mailSettingsPm, userSettingsNone);
+        expect(standard).toBe(getProtonMailSignature());
+        expect(standard).not.toContain(REFERRAL_LINK);
+
+        // PMSignature disabled
+        expect(getProtonSignature({ PMSignature: 0 } as MailSettings, userSettingsReferral)).toBe('');
+        // referral setting off
+        expect(getProtonSignature({ ...mailSettingsPm, PMSignatureReferralLink: 0 }, userSettingsReferral)).toBe(getProtonMailSignature());
+        // empty referral link
+        expect(getProtonSignature(mailSettingsPm, { Referral: { Link: '', Eligible: true } } as UserSettings)).toBe(getProtonMailSignature());
+    });
+
+    it('templateBuilder embeds referral link exactly once and leaves user signature unchanged when disabled', () => {
+        const html = templateBuilder('my signature', mailSettingsPm, undefined, false, false, userSettingsReferral);
+        expect(count(html, REFERRAL_LINK)).toBe(1);
+        expect(html).toContain('my signature');
+
+        const disabled = templateBuilder('my signature', mailSettingsPm, undefined, false, false, userSettingsNone);
+        expect(disabled).not.toContain(REFERRAL_LINK);
+        expect(disabled).toContain('my signature');
+    });
+
+    it('templateBuilder collapses consecutive line breaks and preserves inline tags', () => {
+        const sig = `\n\n<strong>bold\nline</strong>`;
+        const html = templateBuilder(sig, { PMSignature: 0 } as MailSettings, undefined, false, true, userSettingsNone);
+        expect(html).toContain('<br><strong>bold<br>line</strong>');
+        expect(html).not.toContain('<br><br>');
+    });
+
+    it('insertSignature contains the referral link once and keeps spacing rules', () => {
+        // REPLY + PM signature + user signature = 4 spaces
+        const result = insertSignature('<p>test</p>', 'my signature', MESSAGE_ACTIONS.REPLY, mailSettingsPm, undefined, false, userSettingsReferral);
+        expect(count(result, REFERRAL_LINK)).toBe(1);
+        expect((result.match(/<div><br><\/div>/g) || []).length).toBe(4);
+
+        // NEW + PM signature + user signature = 2 (start) + 1 (between) = 3 spaces
+        const newResult = insertSignature('<p>test</p>', 'my signature', MESSAGE_ACTIONS.NEW, mailSettingsPm, undefined, false, userSettingsReferral);
+        expect((newResult.match(/<div><br><\/div>/g) || []).length).toBe(3);
+        expect(count(newResult, REFERRAL_LINK)).toBe(1);
+
+        // signature strictly before the body when isAfter=false
+        const before = insertSignature('<p>test</p>', '', MESSAGE_ACTIONS.NEW, mailSettingsPm, undefined, false, userSettingsReferral);
+        expect(before.indexOf('<p>test</p>')).toBeGreaterThan(before.indexOf(REFERRAL_LINK));
+        // strictly after when isAfter=true
+        const after = insertSignature('<p>test</p>', '', MESSAGE_ACTIONS.NEW, mailSettingsPm, undefined, true, userSettingsReferral);
+        expect(after.indexOf('<p>test</p>')).toBeLessThan(after.indexOf(REFERRAL_LINK));
+    });
+
+    it('changeSignature replaces the proton signature for the new sender', () => {
+        const content = insertSignature('<p>test</p>', 'my signature', MESSAGE_ACTIONS.REPLY, mailSettingsPm, undefined, false, userSettingsReferral);
+        const newDoc = document.implementation.createHTMLDocument();
+        newDoc.body.innerHTML = content;
+
+        const message = {
+            data: { MIMEType: 'text/html' },
+            draftFlags: { action: MESSAGE_ACTIONS.REPLY },
+            messageDocument: { document: newDoc.body },
+        } as unknown as Parameters<typeof changeSignature>[0];
+
+        // Switch to a sender without referral link
+        const updated = changeSignature(message, mailSettingsPm, undefined, 'my signature', 'my signature', userSettingsNone);
+        expect(count(updated, REFERRAL_LINK)).toBe(0);
+        expect(updated).toContain(getProtonMailSignature());
+
+        // Switch back to referral sender
+        const updated2 = changeSignature(message, mailSettingsPm, undefined, 'my signature', 'my signature', userSettingsReferral);
+        expect(count(updated2, REFERRAL_LINK)).toBe(1);
+    });
+
+    it('changeSignature works on plain text drafts', () => {
+        const body = `my draft body\n${sigText('old sig', userSettingsReferral)}`;
+        const message = {
+            data: { MIMEType: 'text/plain' },
+            draftFlags: { action: MESSAGE_ACTIONS.REPLY },
+            messageDocument: { plainText: body },
+        } as unknown as Parameters<typeof changeSignature>[0];
+
+        const updated = changeSignature(message, mailSettingsPm, undefined, 'old sig', 'new sig', userSettingsReferral);
+        expect(count(updated, REFERRAL_LINK)).toBe(1);
+        expect(updated).toContain('new sig');
+        expect(updated).not.toContain('old sig');
+    });
+
+    it('textToHtml includes the referral link exactly once', () => {
+        const input = `Hello\nworld\n${sigText('my signature', userSettingsReferral)}`;
+        const html = textToHtml(input, 'my signature', mailSettingsPm, userSettingsReferral);
+        expect(count(html, REFERRAL_LINK)).toBe(1);
+        expect(html).toContain('Hello<br>');
+
+        const noReferral = textToHtml(`Hello\n${sigText('my signature', userSettingsNone)}`, 'my signature', mailSettingsPm, userSettingsNone);
+        expect(noReferral).not.toContain(REFERRAL_LINK);
+    });
+
+    it('createNewDraft inserts referral signature at the end of the body', () => {
+        const result = createNewDraft(
+            MESSAGE_ACTIONS.NEW,
+            undefined,
+            mailSettingsPm,
+            addresses,
+            jest.fn(),
+            false,
+            userSettingsReferral
+        );
+        const inner = (result.messageDocument?.document as Element)?.innerHTML || '';
+        expect(count(inner, REFERRAL_LINK)).toBe(1);
+        expect(inner).toContain('my signature');
+    });
+
+    it('generateBlockquote includes referral signature in plain text reference', () => {
+        const makeReference = (body: string) =>
+            ({
+                data: {
+                    ID: 'ID',
+                    MIMEType: 'text/plain',
+                    Subject: 'test',
+                    Sender: { Name: 'Sender', Address: 'sender@example.com' },
+                    ToList: [{ Address: 'email' }],
+                },
+                decryption: { decryptedBody: body },
+            } as unknown as MessageStateWithData);
+
+        const blockquote = generateBlockquote(
+            makeReference(`plain body\n${sigText('my signature', userSettingsReferral)}`),
+            mailSettingsPm,
+            addresses,
+            userSettingsReferral
+        );
+        expect(count(blockquote, REFERRAL_LINK)).toBe(1);
+
+        const without = generateBlockquote(
+            makeReference(`plain body\n${sigText('my signature', userSettingsNone)}`),
+            mailSettingsPm,
+            addresses,
+            userSettingsNone
+        );
+        expect(without).not.toContain(REFERRAL_LINK);
+    });
+
+    it('createNewDraft reply keeps a single referral signature (body + blockquote)', () => {
+        const referenceDoc = document.implementation.createHTMLDocument();
+        referenceDoc.body.innerHTML = '<p>original body</p>';
+        const reference = {
+            data: {
+                ID: 'ID',
+                MIMEType: 'text/html',
+                Subject: 'test',
+                Sender: { Name: 'Sender', Address: 'sender@example.com' },
+                ToList: [{ Address: 'me@example.com' }],
