+/**
+ * Creates a type with all properties and nested properties of `T` made optional, recursively.
+ * Primitive types and array types are preserved as-is.
+ */
+export type DeepPartial<T> = T extends readonly unknown[]
+    ? T
+    : T extends object
+    ? {
+          [P in keyof T]?: DeepPartial<T[P]>;
+      }
+    : T;

