+import { renderHook } from '@testing-library/react-hooks';
+
+import { EVENT_ACTIONS } from '@proton/shared/lib/constants';
+
+import EventManagerContext from '../../containers/eventManager/context';
+import { interval, maxPollingSteps, usePollEvents } from './usePollEvents';
+
+type MockEvent = Record<string, unknown>;
+
+const createMockEventManager = () => {
+    const listeners: ((event: MockEvent) => void)[] = [];
+    const unsubscribeSpy = jest.fn();
+
+    const eventManager = {
+        call: jest.fn().mockResolvedValue(undefined),
+        subscribe: jest.fn((listener: (event: MockEvent) => void) => {
+            listeners.push(listener);
+            return () => {
+                unsubscribeSpy();
+                const index = listeners.indexOf(listener);
+                if (index !== -1) {
+                    listeners.splice(index, 1);
+                }
+            };
+        }),
+    };
+
+    const notify = (event: MockEvent) => {
+        // Copy the listeners so that unsubscribing inside a handler doesn't affect iteration.
+        [...listeners].forEach((listener) => listener(event));
+    };
+
+    return {
+        eventManager,
+        notify,
+        unsubscribeSpy,
+        activeSubscriptionCount: () => listeners.length,
+    };
+};
+
+const paymentMethodCreateEvent = (ID: string): MockEvent => ({
+    PaymentMethods: [{ ID, Action: EVENT_ACTIONS.CREATE, PaymentMethod: {} }],
+});
+
+const renderPollEvents = (eventManager: unknown) =>
+    renderHook(() => usePollEvents(), {
+        wrapper: ({ children }: any) => (
+            <EventManagerContext.Provider value={eventManager as any}>{children}</EventManagerContext.Provider>
+        ),
+    });
+
+describe('usePollEvents', () => {
+    beforeEach(() => {
+        jest.clearAllMocks();
+        jest.useFakeTimers();
+    });
+
+    afterEach(() => {
+        jest.useRealTimers();
+    });
+
+    it('exposes the polling interval and the maximum number of polling steps', () => {
+        expect(interval).toBe(5000);
+        expect(maxPollingSteps).toBe(5);
+    });
+
+    it('returns a callable polling function that resolves', async () => {
+        const { eventManager } = createMockEventManager();
+        const { result } = renderPollEvents(eventManager);
+
+        expect(typeof result.current).toBe('function');
+
+        const promise = result.current();
+        expect(promise).toBeInstanceOf(Promise);
+
+        for (let step = 1; step <= maxPollingSteps; step += 1) {
+            await jest.advanceTimersByTimeAsync(interval);
+        }
+
+        await expect(promise).resolves.toBeUndefined();
+        expect(eventManager.call).toHaveBeenCalledTimes(maxPollingSteps);
+    });
+
+    it('calls the event manager once per interval and never exceeds the maximum number of attempts', async () => {
+        const { eventManager } = createMockEventManager();
+        const { result } = renderPollEvents(eventManager);
+
+        const promise = result.current();
+
+        await jest.advanceTimersByTimeAsync(interval - 1000);
+        expect(eventManager.call).not.toHaveBeenCalled();
+
+        await jest.advanceTimersByTimeAsync(1000);
+        expect(eventManager.call).toHaveBeenCalledTimes(1);
+
+        await jest.advanceTimersByTimeAsync(interval - 1000);
+        expect(eventManager.call).toHaveBeenCalledTimes(1);
+
+        await jest.advanceTimersByTimeAsync(1000);
+        expect(eventManager.call).toHaveBeenCalledTimes(2);
+
+        for (let step = 3; step <= maxPollingSteps; step += 1) {
+            await jest.advanceTimersByTimeAsync(interval);
+            expect(eventManager.call).toHaveBeenCalledTimes(step);
+        }
+
+        await promise;
+
+        // Let a bunch more time pass: no further calls beyond the configured maximum.
+        await jest.advanceTimersByTimeAsync(interval * 10);
+        expect(eventManager.call).toHaveBeenCalledTimes(maxPollingSteps);
+    });
+
+    it('does not subscribe to the event manager when no property and action are provided', async () => {
+        const { eventManager } = createMockEventManager();
+        const { result } = renderPollEvents(eventManager);
+
+        const promise = result.current();
+        expect(eventManager.subscribe).not.toHaveBeenCalled();
+
+        for (let step = 1; step <= maxPollingSteps; step += 1) {
+            await jest.advanceTimersByTimeAsync(interval);
+        }
+        await promise;
+    });
+
+    it('subscribes for the duration of the polling window and stops early on the matching event', async () => {
+        const { eventManager, notify, unsubscribeSpy, activeSubscriptionCount } = createMockEventManager();
+        const { result } = renderPollEvents(eventManager);
+
+        const promise = result.current({ propertyKey: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+
+        expect(eventManager.subscribe).toHaveBeenCalledTimes(1);
+        expect(activeSubscriptionCount()).toBe(1);
+
+        await jest.advanceTimersByTimeAsync(interval / 2);
+        expect(eventManager.call).not.toHaveBeenCalled();
+
+        notify(paymentMethodCreateEvent('payment-method-1'));
+
+        // No further calls after the early stop.
+        await jest.advanceTimersByTimeAsync(interval * maxPollingSteps);
+        expect(eventManager.call).not.toHaveBeenCalled();
+
+        await promise;
+        expect(unsubscribeSpy).toHaveBeenCalledTimes(1);
+        expect(activeSubscriptionCount()).toBe(0);
+    });
+
+    it('stops early when the expected event is returned by the event manager call itself', async () => {
