+
+        const promise = result.current({ propertyKey: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+
+        await jest.advanceTimersByTimeAsync(interval);
+        expect(eventManager.call).toHaveBeenCalledTimes(1);
+
+        await jest.advanceTimersByTimeAsync(interval);
+        expect(eventManager.call).toHaveBeenCalledTimes(2);
+
+        // The matching event observed during the second call stops the polling.
+        await jest.advanceTimersByTimeAsync(interval * maxPollingSteps);
+        expect(eventManager.call).toHaveBeenCalledTimes(2);
+
+        await promise;
+    });
+
+    it('continues polling when the observed event has a different property', async () => {
+        const { eventManager, notify, activeSubscriptionCount } = createMockEventManager();
+        const { result } = renderPollEvents(eventManager);
+
+        const promise = result.current({ propertyKey: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+
+        await jest.advanceTimersByTimeAsync(interval / 2);
+        notify({ Addresses: [{ ID: 'address-1', Action: EVENT_ACTIONS.CREATE, Address: {} }] });
+        expect(eventManager.call).not.toHaveBeenCalled();
+        expect(activeSubscriptionCount()).toBe(1);
+
+        for (let step = 1; step <= maxPollingSteps; step += 1) {
+            await jest.advanceTimersByTimeAsync(interval);
+            expect(eventManager.call).toHaveBeenCalledTimes(step);
+        }
+
+        await promise;
+        expect(activeSubscriptionCount()).toBe(0);
+    });
+
+    it('continues polling when the observed event has a different action', async () => {
+        const { eventManager, notify } = createMockEventManager();
+        const { result } = renderPollEvents(eventManager);
+
+        const promise = result.current({ propertyKey: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+
+        await jest.advanceTimersByTimeAsync(interval / 2);
+        notify({ PaymentMethods: [{ ID: 'payment-method-1', Action: EVENT_ACTIONS.UPDATE, PaymentMethod: {} }] });
+        expect(eventManager.call).not.toHaveBeenCalled();
+
+        for (let step = 1; step <= maxPollingSteps; step += 1) {
+            await jest.advanceTimersByTimeAsync(interval);
+            expect(eventManager.call).toHaveBeenCalledTimes(step);
+        }
+
+        await promise;
+        expect(eventManager.call).toHaveBeenCalledTimes(maxPollingSteps);
+    });
+
+    it('unsubscribes when the maximum number of attempts is exhausted', async () => {
+        const { eventManager, unsubscribeSpy, activeSubscriptionCount } = createMockEventManager();
+        const { result } = renderPollEvents(eventManager);
+
+        const promise = result.current({ propertyKey: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+
+        for (let step = 1; step <= maxPollingSteps; step += 1) {
+            await jest.advanceTimersByTimeAsync(interval);
+        }
+        await promise;
+
+        expect(eventManager.subscribe).toHaveBeenCalledTimes(1);
+        expect(unsubscribeSpy).toHaveBeenCalledTimes(1);
+        expect(activeSubscriptionCount()).toBe(0);
+    });
+
+    it('ignores events that arrive after polling has completed by exhausting the attempts', async () => {
+        const { eventManager, notify } = createMockEventManager();
+        const { result } = renderPollEvents(eventManager);
+
+        const promise = result.current({ propertyKey: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+
+        for (let step = 1; step <= maxPollingSteps; step += 1) {
+            await jest.advanceTimersByTimeAsync(interval);
+        }
+        await promise;
+
+        // A matching event arriving after completion must not trigger any further call.
+        notify(paymentMethodCreateEvent('payment-method-1'));
+        await jest.advanceTimersByTimeAsync(interval * maxPollingSteps);
+        expect(eventManager.call).toHaveBeenCalledTimes(maxPollingSteps);
+    });
+
+    it('ignores events that arrive after polling has completed by early stop', async () => {
+        const { eventManager, notify } = createMockEventManager();
+        const { result } = renderPollEvents(eventManager);
+
+        const promise = result.current({ propertyKey: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+
+        notify(paymentMethodCreateEvent('payment-method-1'));
+        await promise;
+
+        // A duplicate or late matching event must not restart polling or trigger further calls.
+        notify(paymentMethodCreateEvent('payment-method-1'));
+        await jest.advanceTimersByTimeAsync(interval * maxPollingSteps);
+        expect(eventManager.call).not.toHaveBeenCalled();
+    });
+
+    it('removes the subscription and rejects the polling promise when an event manager call fails', async () => {
+        const { eventManager, unsubscribeSpy, activeSubscriptionCount } = createMockEventManager();
+        eventManager.call.mockRejectedValue(new Error('network error'));
+
+        const { result } = renderPollEvents(eventManager);
+
+        const promise = result.current({ propertyKey: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+        const expectation = expect(promise).rejects.toThrow('network error');
+
+        await jest.advanceTimersByTimeAsync(interval);
+        await expectation;
+
+        expect(unsubscribeSpy).toHaveBeenCalledTimes(1);
+        expect(activeSubscriptionCount()).toBe(0);
+    });
+
+    it('can be used again after a completed session', async () => {
+        const { eventManager } = createMockEventManager();
+        const { result } = renderPollEvents(eventManager);
+
+        const first = result.current();
+        for (let step = 1; step <= maxPollingSteps; step += 1) {
+            await jest.advanceTimersByTimeAsync(interval);
+        }
+        await first;
+
+        const second = result.current();
+        for (let step = 1; step <= maxPollingSteps; step += 1) {
+            await jest.advanceTimersByTimeAsync(interval);
+        }
+        await second;
+
+        expect(eventManager.call).toHaveBeenCalledTimes(maxPollingSteps * 2);
+    });
+
+    it('does not complete multiple times when several matching events arrive in a row', async () => {
+        const { eventManager, notify, unsubscribeSpy, activeSubscriptionCount } = createMockEventManager();
+        const { result } = renderPollEvents(eventManager);
+
+        const promise = result.current({ propertyKey: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+
+        notify(paymentMethodCreateEvent('payment-method-1'));
+        notify(paymentMethodCreateEvent('payment-method-2'));
+
+        await promise;
+
+        expect(eventManager.subscribe).toHaveBeenCalledTimes(1);
+        expect(unsubscribeSpy).toHaveBeenCalledTimes(1);
+        expect(activeSubscriptionCount()).toBe(0);
+
+        await jest.advanceTimersByTimeAsync(interval * maxPollingSteps);
+        expect(eventManager.call).not.toHaveBeenCalled();
+    });
+});
